(function(A){Object.assign(A.D,{"G3870":{"l":"παρακαλέω","o":109,"ar":"<f><o>παρα-καλέω</o>، <g>-ῶ</g>،</f> <s> <s n=\"1.\"><b>يدعو</b> إليه، <b>يستدعي</b>، <b>يطلب حضور</b>: <r v=\"Acts.28.20\"></r>؛ ومن ثم <b>يستغيث بـ</b>، <b>يدعو</b>، <b>يتوسل</b>، <b>يطلب</b>: <g>τ. πατέρα μου</g>، <r v=\"Matt.26.53\"></r>؛ <g>τ. κύριον</g>، <r v=\"2Cor.12.8\"></r>؛ وفي الكتابات المتأخرة يُقال أيضًا عن البشر: مطلقًا، <r v=\"Phlm.1.9\"></r>؛ مع المنصوب، <r v=\"Matt.8.5\"></r>، <r v=\"Mark.1.40\"></r>، <r v=\"Acts.16.9\"></r>، وفي مواضع أخرى؛ مع المصدر، <r v=\"Mark.5.17\"></r>، <r v=\"Luke.8.41\"></r>، <r v=\"Acts.8.31\"></r>، وفي مواضع أخرى؛ يليه <g>ἵνα</g>، <r v=\"Matt.14.36\"></r>، <r v=\"Mark.5.18\"></r>، <r v=\"Luke.8.31\"></r>، وفي مواضع أخرى.</s> <s n=\"2.\"><b>يَعِظ</b>، <b>يحثّ</b>: مطلقًا، <r v=\"Luke.3.18\"></r>، <r v=\"Rom.12.8\"></r>، <r v=\"2Tim.4.2\"></r>، وفي مواضع أخرى؛ مع المنصوب، <r v=\"Acts.15.32\"></r>، <r v=\"1Thess.2.11\"></r>، <r v=\"Heb.3.13\"></r>، وفي مواضع أخرى؛ والتعبير نفسه يليه المصدر، <r v=\"Acts.11.23\"></r>، <r v=\"Rom.12.1\"></r>، <r v=\"Phil.4.2\"></r>، <r v=\"1Thess.4.10\"></r>، وفي مواضع أخرى؛ يليه <g>ἵνα</g>، <r v=\"1Cor.1.10\"></r>، <r v=\"2Cor.8.6\"></r>، <r v=\"1Thess.4.1\"></r>، وفي مواضع أخرى.</s> <s n=\"3.\"><b>يُشجِّع</b>، <b>يُشدِّد</b>، <b>يُعزّي</b> (السبعينية: <r v=\"Job.4.3\"></r>، <r v=\"Isa.35.3\"></r>، <r v=\"Sir.43.24\"></r>، وفي مواضع أخرى): مع المنصوب، <r v=\"2Cor.1.6\"></r>، <r v=\"Eph.6.22\"></r>، <r v=\"Col.2.2\"></r>، وفي مواضع أخرى؛ والتعبير نفسه يليه <g>ἐν</g>، <r v=\"1Thess.4.18\"></r>؛ <g>διά</g>، <r v=\"2Cor.1.4\"></r>؛ المبني للمجهول، <r v=\"Matt.5.4\"></r>، <r v=\"Luke.16.25\"></r>، <r v=\"Acts.20.12\"></r>.</s> </s>","en":"<f><o>παρα-καλέω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5162\">נחם</h> ni., pi.;]</e> </et> <s> <s n=\"1.\"><b>to call to</b> one, <b>call for</b>, <b>summon</b>: <r v=\"Acts.28.20\"></r> (R, mg.; R, txt., <i>entreat</i>); hence (of the gods: Dem., Xen., al.), <b>to invoke</b>, <b>call on</b>, <b>beseech</b>, <b>entreat</b>: <g>τ. πατέρα μου</g>, <r v=\"Matt.26.53\"></r>; <g>τ. κύριον</g>, <r v=\"2Cor.12.8\"></r>; in late writers (Polyb., Diod., al.; rarely in LXX; in <g>π.</g>, v. Deiss., <i>LAE</i>, 176<i>14</i>), also of men: absol., <r v=\"Phlm.1.9\"></r>; c. acc., <r v=\"Matt.8.5\"></r>, <r v=\"Mark.1.40\"></r>, <r v=\"Acts.16.9\"></r>, al.; c. inf., <r v=\"Mark.5.17\"></r>, <r v=\"Luke.8.41\"></r>, <r v=\"Acts.8.31\"></r>, al.; seq. <g>ἵνα</g> (v. M, <i>Pr.</i>, 205, 208), <r v=\"Matt.14.36\"></r>, <r v=\"Mark.5.18\"></r>, <r v=\"Luke.8.31\"></r>, al.</s> <s n=\"2.\"><b>to admonish</b>, <b>exhort</b>: absol., <r v=\"Luke.3.18\"></r>, <r v=\"Rom.12.8\"></r>, <r v=\"2Tim.4.2\"></r>, al.; c. acc., <r v=\"Acts.15.32\"></r>, <r v=\"1Thess.2.11\"></r>, <r v=\"Heb.3.13\"></r>, al.; id. seq. inf., <r v=\"Acts.11.23\"></r>, <r v=\"Rom.12.1\"></r>, <r v=\"Phil.4.2\"></r>, <r v=\"1Thess.4.10\"></r>, al.; seq. <g>ἵνα</g> (v. M, <i>Pr.</i>, 205, 208), <r v=\"1Cor.1.10\"></r>, <r v=\"2Cor.8.6\"></r>, <r v=\"1Thess.4.1\"></r>, al.</s> <s n=\"3.\"><b>to cheer</b>, <b>encourage</b>, <b>comfort</b> (Plut., LXX: <r v=\"Job.4.3\"></r>, <r v=\"Isa.35.3\"></r>, <r v=\"Sir.43.24\"></r>, al.): c. acc., <r v=\"2Cor.1.6\"></r>, <r v=\"Eph.6.22\"></r>, <r v=\"Col.2.2\"></r>, al.; id. seq. <g>ἐν</g>, <r v=\"1Thess.4.18\"></r>; <g>διά</g>, <r v=\"2Cor.1.4\"></r>; pass., <r v=\"Matt.5.4\"></r>, <r v=\"Luke.16.25\"></r>, <r v=\"Acts.20.12\"></r>.</s> </s> <sy><i>SYN.</i>: <g>παραμυθέω</g> (cf. M, <i>Th.</i>, 25).</sy>"},"G3842":{"l":"πάντοτε","o":41,"ar":"<f>** <o>πάντοτε</o>،</f> ظرف زمان <s><b>في كل حين</b>، <b>دائمًا</b>: <r v=\"Matt.26.11\"></r>، <r v=\"Mark.14.7\"></r>، <r v=\"Luke.15.31\"></r>، <r v=\"John.6.34\"></r>، <r v=\"Rom.1.10\"></r>، وكثيرًا في رسائل بولس.</s>","en":"<f>** <o>πάντοτε</o>,</f> adv. of time <et> <e t=\"derivation\">(&lt; <g>πᾶς</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Wis.11.21\"></r> <r v=\"Wis.19.18\"></r>*;]</e> <e t=\"derivation\">in late writers (once in Arist.) for <g>διαπαντός</g>, <g>ἑκάστοτε</g>,</e> </et> <s><b>at all times</b>, <b>always</b>: <r v=\"Matt.26.11\"></r>, <r v=\"Mark.14.7\"></r>, <r v=\"Luke.15.31\"></r>, <r v=\"John.6.34\"></r>, <r v=\"Rom.1.10\"></r>, and freq. in Paul. Epp.</s>"},"G3874":{"l":"παράκλησις","o":29,"ar":"<f><o>παρά-κλησις</o>، <g>-εως, ἡ</g></f> <s n=\"1.\"><b>استدعاء أحد للعون</b>، <b>دعوة</b>، ومن هنا <b>التماس</b>، <b>توسّل</b> (قارن <r v=\"1Macc.10.24\"></r>): <r v=\"2Cor.8.4\"></r>.</s> <s n=\"2.\"><b>وعظ، حثّ</b>، <b>تشجيع</b>: <r v=\"Acts.15.31\"></r>، <r v=\"Rom.12.8\"></r>، <r v=\"1Cor.14.3\"></r>، <r v=\"2Cor.8.17\"></r>، <r v=\"Phil.2.1\"></r>، <r v=\"1Thess.2.3\"></r>، <r v=\"1Tim.4.13\"></r>، <r v=\"Heb.12.5\"></r>؛ <g>λόγος</g> (<g>τῆς</g>) <g>π.</g>: <r v=\"Acts.13.15\"></r>، <r v=\"Heb.13.22\"></r>؛ <g>υἱὸς π.</g>: <r v=\"Acts.4.36\"></r>.</s> <s n=\"3.\"><b>تعزية</b>، <b>عزاء</b>: <r v=\"Luke.6.24\"></r>، <r v=\"Acts.9.31\"></r>، <r v=\"2Cor.1.4-2Cor.1.7\"></r>، <r v=\"2Cor.7.4\"></r>، <r v=\"2Cor.7.7\"></r>، <r v=\"2Cor.7.13\"></r>، <r v=\"2Thess.2.16\"></r>، <r v=\"Phlm.1.7\"></r>؛ <g>τ. γραφῶν</g>: <r v=\"Rom.15.4\"></r>؛ <g>θεὸς τῆς π.</g>: <r v=\"Rom.15.5\"></r>، <r v=\"2Cor.1.3\"></r>؛ <g>π. τοῦ Ἰσραήλ</g>: <r v=\"Luke.2.25\"></r>.†</s>","en":"<f><o>παρά-κλησις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>παρακαλέω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Job.21.2\"></r>, <r v=\"Ps.94.19\"></r>, <r v=\"Hos.13.14\"></r>, <r v=\"Nah.3.7\"></r>, <r v=\"Isa.57.18\"></r> <r v=\"Isa.66.11\"></r>, <r v=\"Jer.16.7\"></r> (<h n=\"H5162\">נחם</h>, its parts and derivatives), <r v=\"Jer.31.9\"></r> (<h n=\"H8469\">תַּחֲנוּן</h>), <r v=\"Isa.28.29\"></r> <r v=\"Isa.30.7\"></r>, <r v=\"1Macc.10.24\"></r> <r v=\"1Macc.12.9\"></r>, <r v=\"2Macc.7.24\"></r> <r v=\"2Macc.15.11\"></r>*;]</e> </et> <s n=\"1.\"><b>a calling to one's aid</b>, <b>summons</b> (Thus.), hence, <b>appeal</b>, <b>entreaty</b> (Strab., Plut., al., <r v=\"1Macc.10.24\"></r>; cf. Lft., <i>Notes</i>, 20): <r v=\"2Cor.8.4\"></r>.</s> <s n=\"2.\"><b>exhortation</b>, <b>encouragement</b>: <r v=\"Acts.15.31\"></r>, <r v=\"Rom.12.8\"></r>, <r v=\"1Cor.14.3\"></r>, <r v=\"2Cor.8.17\"></r>, <r v=\"Phil.2.1\"></r>, <r v=\"1Thess.2.3\"></r>, <r v=\"1Tim.4.13\"></r>, <r v=\"Heb.12.5\"></r>; <g>λόγος</g> (<g>τῆς</g>) <g>π.</g>, <r v=\"Acts.13.15\"></r>, <r v=\"Heb.13.22\"></r>; <g>υἱὸς π.</g>, <r v=\"Acts.4.36\"></r>.</s> <s n=\"3.\"><b>consolation</b>, <b>comfort</b> (Phalar., LXX): <r v=\"Luke.6.24\"></r>, <r v=\"Acts.9.31\"></r>, <r v=\"2Cor.1.4-2Cor.1.7\"></r> <r v=\"2Cor.7.4\"></r>, <r v=\"2Cor.7.7\"></r>, <r v=\"2Cor.7.13\"></r>, <r v=\"2Thess.2.16\"></r>, <r v=\"Phlm.1.7\"></r>; <g>τ. γραφῶν</g>, <r v=\"Rom.15.4\"></r>; <g>θεὸς τῆς π.</g>, <r v=\"Rom.15.5\"></r>, <r v=\"2Cor.1.3\"></r>; <g>π. τοῦ Ἰσραήλ</g> (v. Dalman, <i>Words</i>, 109 f.), <r v=\"Luke.2.25\"></r>.†</s>"},"G3809":{"l":"παιδεία","o":6,"ar":"<f><o>παιδεία</o>، <g>-ας, ἡ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>تربية الطفل</b>.</s> <s n=\"2.\"><b>تدريب</b>، <b>تعلّم</b>، <b>تعليم / تهذيب</b>: <r v=\"Eph.6.4\"></r>، <r v=\"2Tim.3.16\"></r>.</s> <s n=\"3.\">كما في السبعينية (<r v=\"Prov.3.11\"></r> <r v=\"Prov.15.5\"></r>، وفي مواضع أخرى)، <b>تأديب</b>، <b>تقويم</b>: <r v=\"Heb.12.5\"></r><i>(السبعينية)</i>، <r v=\"Heb.12.7\"></r>، <r v=\"Heb.12.8\"></r>، <r v=\"Heb.12.11\"></r>.†</s>","en":"<f><o>παιδεία</o> (<g>-ία</g>, T), <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>παιδεύω</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4148\">מוּסָר</h>;]</e> </et> <s n=\"1.\"><b>the rearing of a child</b> (Æsch.).</s> <s n=\"2.\"><b>training</b>, <b>learning</b>, <b>instruction</b> (Plat., al.): <r v=\"Eph.6.4\"></r>, <r v=\"2Tim.3.16\"></r>.</s> <s n=\"3.\">As in LXX (<r v=\"Prov.3.11\"></r> <r v=\"Prov.15.5\"></r>, al.), <b>chastening</b>, <b>discipline</b>: <r v=\"Heb.12.5\"></r><i>(LXX)</i>, <r v=\"Heb.12.7\"></r>, <r v=\"Heb.12.8\"></r>, <r v=\"Heb.12.11\"></r>.†</s>"},"G3823":{"l":"πάλη","o":1,"ar":"<f>* <o>πάλη</o>، <g>-ης, ἡ</g></f> <s><b>مصارعة</b>، ومن ثَمّ عمومًا <b>قتال</b>، نزال: مجازيًا، عن الجهاد الروحي للمسيحيين، <r v=\"Eph.6.12\"></r>.†</s>","en":"<f>* <o>πάλη</o>, <g>-ης, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>πάλλω</g>, <i>to sway</i>)</e> </et> <s><b>wrestling</b>, hence, generally, <b>fight</b>, contest: fig., of the spiritual combat of Christians, <r v=\"Eph.6.12\"></r>.†</s>"},"G3860":{"l":"παραδίδωμι","o":119,"ar":"<f><o>παρα-δίδωμι</o>،</f> <s> <s n=\"1.\"> <b>يُعطي</b> أو <b>يُسلِّم</b> إلى آخر: مع المنصوب والقابل، <r v=\"Matt.11.27\"></r> <r v=\"Matt.25.14\"></r>، <r v=\"Luke.4.6\"></r>، وفي مواضع أخرى؛ عن التسليم إلى صورة من التعليم، المبني للمجهول يليه <g>εἰς</g>، <r v=\"Rom.6.17\"></r>.</s> <s n=\"2.\"><b>يستودع</b>، <b>يُسلِّم (إلى عناية)</b>: <r v=\"Acts.14.26\"></r> <r v=\"Acts.15.40\"></r>، <r v=\"1Pet.2.23\"></r>.</s> <s n=\"3.\"><b>يُسلِّم</b> أو <b>يُسلِم</b> إلى السجن أو القضاء: مع منصوب الشخص، <r v=\"Matt.4.12\"></r>، <r v=\"Mark.1.14\"></r>، <r v=\"Rom.4.25\"></r>، <r v=\"2Pet.2.4\"></r>؛ وهو نفسه يليه <g>ὑπέρ</g>، <r v=\"Rom.8.32\"></r>؛ مع القابل، <r v=\"Matt.5.25\"></r>، <r v=\"Mark.15.1\"></r>، <r v=\"Luke.12.58\"></r>، <r v=\"John.19.11\"></r>، وفي مواضع أخرى؛ وهو نفسه يليه <g>ἵνα</g>، <r v=\"John.19.16\"></r>؛ مع المصدر، <r v=\"Acts.12.4\"></r>؛ يليه <g>εἰς</g>، <r v=\"Matt.10.17\"></r> <r v=\"Matt.17.22\"></r> <r v=\"Matt.24.9\"></r>، <r v=\"Luke.21.12\"></r>، <r v=\"Acts.8.3\"></r>، <r v=\"2Cor.4.11\"></r>، وفي مواضع أخرى؛ <g>τ. Σατανᾷ</g>، <r v=\"1Tim.1.20\"></r>؛ وهو نفسه يليه <g>εἰς ὄλεθρον σαρκός</g>، <r v=\"1Cor.5.5\"></r>؛ مع فكرة مصاحبة هي الخيانة (= <g>προδίδωμι</g>)، مع منصوب الشخص، <r v=\"Matt.26.16\"></r>، <r v=\"Mark.14.11\"></r>، <r v=\"John.6.64\"></r>، وفي مواضع أخرى؛ وهو نفسه مع القابل، <r v=\"Matt.26.15\"></r>، وفي مواضع أخرى؛ اسم الفاعل المضارع، <g>ὁ παραδιδοὺς αὐτόν</g>، <r v=\"Matt.26.25\"></r>، <r v=\"Mark.14.42\"></r>، <r v=\"John.13.11\"></r>.</s> <s n=\"4.\"><b>يُسلِّم (من جيل إلى جيل)</b>، <b>ينقل</b> أو <b>يُسلِّم</b> شفاهًا (التقاليد، الوصايا، إلخ): <r v=\"Mark.7.13\"></r>، <r v=\"Luke.1.2\"></r>، <r v=\"Acts.6.14\"></r>، <r v=\"1Cor.11.2\"></r> <r v=\"1Cor.15.2\"></r>؛ المبني للمجهول، <r v=\"2Pet.2.21\"></r>، <r v=\"Jude.1.3\"></r>.</s> <s n=\"5.\"><b>يسمح</b>: <r v=\"Mark.4.29\"></r>.</s> </s>","en":"<f><o>παρα-δίδωμι</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5414\">נתן</h>;]</e> <e t=\"derivation\">correl. to <g>παρδέχομαι</g>,</e> </et> <s> <s n=\"1.\"> <b>to give</b> or <b>hand over</b> to another: c. acc. et dat., <r v=\"Matt.11.27\"></r> <r v=\"Matt.25.14\"></r>, <r v=\"Luke.4.6\"></r>, al.; of being delivered up to a course of teaching, pass. seq. <g>εἰς</g>, <r v=\"Rom.6.17\"></r>.</s> <s n=\"2.\"><b>to commit</b>, <b>commend</b>: <r v=\"Acts.14.26\"></r> <r v=\"Acts.15.40\"></r>, <r v=\"1Pet.2.23\"></r>.</s> <s n=\"3.\"><b>to give</b> or <b>deliver up</b> to prison or judgment: c. acc. pers., <r v=\"Matt.4.12\"></r>, <r v=\"Mark.1.14\"></r>, <r v=\"Rom.4.25\"></r>, <r v=\"2Pet.2.4\"></r>; id. seq. <g>ὑπέρ</g>, <r v=\"Rom.8.32\"></r>; c. dat., <r v=\"Matt.5.25\"></r>, <r v=\"Mark.15.1\"></r>, <r v=\"Luke.12.58\"></r>, <r v=\"John.19.11\"></r>, al.; id. seq. <g>ἵνα</g>, <r v=\"John.19.16\"></r>; c. inf., <r v=\"Acts.12.4\"></r>; seq. <g>εἰς</g>, <r v=\"Matt.10.17\"></r> <r v=\"Matt.17.22\"></r> <r v=\"Matt.24.9\"></r>, <r v=\"Luke.21.12\"></r>, <r v=\"Acts.8.3\"></r>, <r v=\"2Cor.4.11\"></r>, al.; <g>τ. Σατανᾷ</g>, <r v=\"1Tim.1.20\"></r>; id. seq. <g>εἰς ὄλεθρον σαρκός</g>, <r v=\"1Cor.5.5\"></r>; with the collat. idea of treachery (= <g>προδίδωμι</g>), c. acc. pers., <r v=\"Matt.26.16\"></r>, <r v=\"Mark.14.11\"></r>, <r v=\"John.6.64\"></r>, al.; id. c. dat., <r v=\"Matt.26.15\"></r>, al.; pres. ptcp., <g>ὁ παραδιδοὺς αὐτόν</g>, <r v=\"Matt.26.25\"></r>, <r v=\"Mark.14.42\"></r>, <r v=\"John.13.11\"></r>.</s> <s n=\"4.\"><b>to hand down</b>, <b>hand on</b> or <b>deliver</b> verbally (traditions, commands, etc.): <r v=\"Mark.7.13\"></r>, <r v=\"Luke.1.2\"></r>, <r v=\"Acts.6.14\"></r>, <r v=\"1Cor.11.2\"></r> <r v=\"1Cor.15.2\"></r>; pass., <r v=\"2Pet.2.21\"></r>, <r v=\"Jude.1.3\"></r>.</s> <s n=\"5.\"><b>to permit</b> (for exx. in cl., v. LS, s.v.): <r v=\"Mark.4.29\"></r>.</s> </s>"},"G3820":{"l":"παλαιός","o":19,"ar":"<f><o>παλαιός</o>، <g>-ά, -όν</g></f> <s><b>عتيق</b>، <b>قديم</b>؛ عكس <g>νέος</g>، <g>καινός</g>: <g>οἶνος</g>، <r v=\"Luke.5.39\"></r>؛ <g>διαθήκη</g>، <r v=\"2Cor.3.14\"></r>؛ <g>ἐντολή</g>، <r v=\"1John.2.7\"></r>؛ <g>ζύμη</g>، <r v=\"1Cor.5.7\"></r>، <r v=\"1Cor.5.8\"></r>؛ <g>ὁ π. ἄςθρωπος</g>، <r v=\"Rom.6.6\"></r>، <r v=\"Eph.4.22\"></r>، <r v=\"Col.3.9\"></r>؛ المحايد الجمع، <g>καινὰ καὶ π.</g>، <r v=\"Matt.13.52\"></r>؛ عن أشياء ليست قديمة فحسب، بل بالية من الاستعمال (كما في <r v=\"Josh.9.4\"></r>، <r v=\"Josh.9.5\"></r>، السبعينية)، <r v=\"Matt.9.16\"></r>، <r v=\"Matt.9.17\"></r>، <r v=\"Mark.2.21\"></r>، <r v=\"Mark.2.22\"></r>، <r v=\"Luke.5.36\"></r>، <r v=\"Luke.5.37\"></r>.†</s>","en":"<f><o>παλαιός</o>, <g>-ά, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>πάλαι</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Lev.25.22\"></r> <r v=\"Lev.26.10\"></r>, <r v=\"Song.7.13\"></r> (<r v=\"Song.7.14\"></r>) (<h n=\"H3462\">ישׁן</h>), <r v=\"Josh.9.4\"></r>, <r v=\"Josh.9.5\"></r>, <r v=\"Jer.38.11\"></r> (<h n=\"H1087\">בָּלֶה</h>), etc.;]</e> </et> <s><b>old</b>, <b>ancient</b>; opp. to <g>νέος</g>, <g>καινός</g>: <g>οἶνος</g>, <r v=\"Luke.5.39\"></r>; <g>διαθήκη</g>, <r v=\"2Cor.3.14\"></r>; <g>ἐντολή</g>, <r v=\"1John.2.7\"></r>; <g>ζύμη</g>, <r v=\"1Cor.5.7\"></r>, <r v=\"1Cor.5.8\"></r>; <g>ὁ π. ἄςθρωπος</g> (for similar phrases, v. Westc., <i>Eph.</i>, 68), <r v=\"Rom.6.6\"></r>, <r v=\"Eph.4.22\"></r>, <r v=\"Col.3.9\"></r>; neut. pl., <g>καινὰ καὶ π.</g>, <r v=\"Matt.13.52\"></r>; of things not merely old, but worn by use (as <r v=\"Josh.9.4\"></r>, <r v=\"Josh.9.5\"></r>, LXX), <r v=\"Matt.9.16\"></r>, <r v=\"Matt.9.17\"></r>, <r v=\"Mark.2.21\"></r>, <r v=\"Mark.2.22\"></r>, <r v=\"Luke.5.36\"></r>, <r v=\"Luke.5.37\"></r>.†</s> <sy><i>SYN.</i>: v.s. <g>ἀρχαῖος</g>.</sy>"},"G3834":{"l":"πανουργία","o":5,"ar":"<f><o>πανουργία</o>، <g>-ας, ἡ</g></f> <s><b>حذاقة / دهاء</b>، <b>مكر</b>، <b>خبث</b>، <b>احتيال</b>: <r v=\"Luke.20.23\"></r>، <r v=\"1Cor.3.19\"></r> (في السبعينية <g>φρόνησις</g>، ترجمةً لـ <h n=\"H6195\">עׇרְמָה</h>) <r v=\"2Cor.4.2\"></r> <r v=\"2Cor.11.3\"></r>، <r v=\"Eph.4.14\"></r>.†</s>","en":"<f><o>πανουργία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>πανοῦργος</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Josh.9.4\"></r>, <r v=\"Prov.1.4\"></r> <r v=\"Prov.8.5\"></r> (<h n=\"H6195\">עׇרְמָה</h>), <r v=\"Num.24.22\"></r>, <r v=\"Sir.19.25\"></r> <r v=\"Sir.21.22\"></r> <r v=\"Sir.34.10\"></r> (in all cases in good or indifferent sense)*;]</e> </et> <s><b>cleverness</b>, in cl. nearly always in bad sense, <b>craftiness</b>, <b>cunning</b>, <b>knavery</b>: <r v=\"Luke.20.23\"></r>, <r v=\"1Cor.3.19\"></r> (LXX, <g>φρόνησις</g>, for <h n=\"H6195\">עׇרְמָה</h>) <r v=\"2Cor.4.2\"></r> <r v=\"2Cor.11.3\"></r>, <r v=\"Eph.4.14\"></r>.†</s>"},"G3833":{"l":"πανοπλία","o":3,"ar":"<f><o>πανοπλία</o>، <g>-ας, ἡ</g></f> <s><b>سلاح كامل</b>: <r v=\"Luke.11.22\"></r>؛ مجازيًا (قارن <r v=\"Wis.5.17\"></r>)، <g>τ. θεοῦ</g>، <r v=\"Eph.6.11\"></r>، <r v=\"Eph.6.13\"></r>.†</s>","en":"<f><o>πανοπλία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>πᾶς</g>, <g>ὅπλον</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"2Sam.2.21\"></r> (<h n=\"H2488\">חֲלִיצָה</h>), <r v=\"Job.39.20\"></r>, <r v=\"Jdt.14.3\"></r>, <r v=\"Wis.5.17\"></r>, <r v=\"Sir.46.6\"></r>, I, II, IV Mac<i>6</i>*;]</e> </et> <s><b>full armour</b>: <r v=\"Luke.11.22\"></r>; metaph. (cf. <r v=\"Wis.5.17\"></r>), <g>τ. θεοῦ</g>, <r v=\"Eph.6.11\"></r>, <r v=\"Eph.6.13\"></r>.†</s>"},"G3825":{"l":"πάλιν","o":141,"ar":"<f><o>πάλιν</o>، ظرف،</f> <s n=\"1.\">في اليونانية الكلاسيكية: للمكان، <b>إلى الوراء</b>، <b>رجوعًا</b>.</s> <s n=\"2.\">للزمان، <b>أيضًا، ثانيةً</b>، <b>مرة أخرى</b>: <r v=\"Matt.4.8\"></r>، <r v=\"Mark.2.13\"></r>، <r v=\"Luke.23.20\"></r>، <r v=\"John.1.35\"></r> (وكثيرًا)، <r v=\"Acts.17.32\"></r>، <r v=\"Rom.11.23\"></r>، <r v=\"Gal.1.9\"></r>، <r v=\"Heb.1.6\"></r>، وفي مواضع أخرى؛ على سبيل الحشو (التكرار)، <g>π. ἀνακάμπτειν</g>، <r v=\"Acts.18.21\"></r>؛ <g>ὑποστρέφειν</g>، <r v=\"Gal.1.17\"></r>؛ <g>εἰς τὸ π.</g>، <r v=\"2Cor.13.2\"></r>؛ <g>π. ἐκ τρίτου</g>، <r v=\"Matt.26.44\"></r>؛ <g>ἐκ δευτέρου</g>، <r v=\"Matt.26.42\"></r>، <r v=\"Acts.10.15\"></r>؛ <g>π. δεῦτερον</g>، <r v=\"John.4.54\"></r> <r v=\"John.21.16\"></r>؛ <g>π. ἄνωθεν</g> (<r v=\"Wis.19.6\"></r>)، <r v=\"Gal.4.9\"></r>.</s> <s n=\"3.\">في أسلوب الكلام، <b>أيضًا</b>؛ <s n=\"(a)\"><b>وكذلك</b>، <b>علاوةً على ذلك</b>: <r v=\"Matt.5.33\"></r>، <r v=\"Luke.13.20\"></r>، <r v=\"John.12.39\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\"><b>بدوره</b>، <b>ومن جهة أخرى</b> (وفي السبعينية: <r v=\"Wis.13.8\"></r> <r v=\"Wis.16.23\"></r>، وفي مواضع أخرى): <r v=\"Luke.6.43\"></r>، <r v=\"1Cor.12.21\"></r>، <r v=\"2Cor.10.7\"></r>، <r v=\"1John.2.8\"></r>.</s> </s>","en":"<f><o>πάλιν</o>, adv.,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H7725\">שׁוּב</h>, etc.;]</e> </et> <s n=\"1.\">of place, <b>back</b>, <b>backwards</b> (LS, s.v.).</s> <s n=\"2.\">Of time, <b>again</b>, <b>once more</b>: <r v=\"Matt.4.8\"></r>, <r v=\"Mark.2.13\"></r>, <r v=\"Luke.23.20\"></r>, <r v=\"John.1.35\"></r> (and freq.), <r v=\"Acts.17.32\"></r>, <r v=\"Rom.11.23\"></r>, <r v=\"Gal.1.9\"></r>, <r v=\"Heb.1.6\"></r>, al; pleonastically, <g>π. ἀνακάμπτειν</g>, <r v=\"Acts.18.21\"></r>; <g>ὑποστρέφειν</g>, <r v=\"Gal.1.17\"></r>; <g>εἰς τὸ π.</g>, <r v=\"2Cor.13.2\"></r>; <g>π. ἐκ τρίτου</g> (Bl., § 81, 4), <r v=\"Matt.26.44\"></r>; <g>ἐκ δευτέρου</g>, <r v=\"Matt.26.42\"></r>, <r v=\"Acts.10.15\"></r>; <g>π. δεῦτερον</g>, <r v=\"John.4.54\"></r> <r v=\"John.21.16\"></r>; <g>π. ἄνωθεν</g> ( <r v=\"Wis.19.6\"></r>), <r v=\"Gal.4.9\"></r>.</s> <s n=\"3.\">Rhetorically, <b>again</b>; <s n=\"(a)\"><b>further</b>, <b>moreover</b>: <r v=\"Matt.5.33\"></r>, <r v=\"Luke.13.20\"></r>, <r v=\"John.12.39\"></r>, al.;</s> <s n=\"(b)\"><b>in turn</b>, <b>on the other hand</b> (Soph.; LXX: <r v=\"Wis.13.8\"></r> <r v=\"Wis.16.23\"></r>, al.): <r v=\"Luke.6.43\"></r>, <r v=\"1Cor.12.21\"></r>, <r v=\"2Cor.10.7\"></r>, <r v=\"1John.2.8\"></r>.</s> </s>"},"G3807":{"l":"παιδαγωγός","o":3,"ar":"<f>* <o>παιδαγωγός</o>، <g>-οῦ, ὁ</g></f> <s>مرشد الصبيان وحارسهم ومربّيهم، <b>مؤدِّب</b> (يُميَّز عن <g>διδάσκαλος</g>)، وكان عادةً عبدًا أمينًا: عكس <g>πατήρ</g>، <r v=\"1Cor.4.15\"></r>؛ مجازيًا، عن الناموس، <g>π. εἰς Χριστόν</g>، <r v=\"Gal.3.24\"></r>، <r v=\"Gal.3.25\"></r>.†</s>","en":"<f>* <o>παιδαγωγός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>παῖς</g>, <g>ἄγω</g>),</e> </et> <s>a guide, guardian, trainer of boys, <b>a tutor</b> (disting. from <g>διδάσκαλος</g>, Xen., <i>Lac.</i>, 3, 1), usually a trusty slave: opp. to <g>πατήρ</g>, <r v=\"1Cor.4.15\"></r>; fig., of the Law, <g>π. εἰς Χριστόν</g>, <r v=\"Gal.3.24\"></r>, <r v=\"Gal.3.25\"></r>.†</s>"},"G3889":{"l":"παραμυθία","o":1,"ar":"<f>** <o>παραμυθία</o>، <g>-ας, ἡ</g></f> <s n=\"1.\"><b>تشجيع</b>، <b>حثّ</b>.</s> <s n=\"2.\"><b>تعزية</b>، <b>سلوى</b>: <r v=\"1Cor.14.3\"></r>.†</s>","en":"<f>** <o>παραμυθία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>παραμυθέομαι</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Ezra.8.13\"></r>, <r v=\"Wis.19.12\"></r>*;]</e> </et> <s n=\"1.\"><b>encouragement</b>, <b>exhortation</b>.</s> <s n=\"2.\"><b>comfort</b>, <b>consolation</b>: <r v=\"1Cor.14.3\"></r>.†</s> <sy><i>SYN.</i>: <g>παράκλησις</g>.</sy>"},"G3859":{"l":"παραδιατριβή","o":1,"ar":"<f>*† <o>παρα-δια-τριβή</o>، <g>-ῆς, ἡ</g>،</f> <s><b>مجادلة عقيمة</b>: قراءة بديلة في النص المستلَم بدل <g>διαπαρατριβή</g> (انظره)، <r v=\"1Tim.6.5\"></r>.†</s>","en":"<f>*† <o>παρα-δια-τριβή</o>, <g>-ῆς, ἡ</g>,</f> <s><b>useless wrangling</b>: v.l. in Rec. for <g>διαπαρατριβή</g> (q.v.), <r v=\"1Tim.6.5\"></r>.†</s>"},"G3855":{"l":"παράγω","o":10,"ar":"<f><o>παρ-άγω</o>،</f> <s n=\"1.\">متعدٍّ: <b>يقود بجانب</b>، <b>يقود جانبًا</b>، <b>يُدخِل</b>، <b>يُقدِّم</b>، إلخ.</s> <s n=\"2.\">لازم، <s n=\"(a)\"><b>يجتاز</b>، <b>يمرّ</b>: <r v=\"Matt.9.9\"></r>، <r v=\"Matt.9.27\"></r> <r v=\"Matt.20.30\"></r>، <r v=\"Mark.2.14\"></r> <r v=\"Mark.15.21\"></r>، <r v=\"John.8.59\"></r>، <r v=\"John.9.1\"></r>؛ يليه <g>παρό</g> مع المنصوب، <r v=\"Mark.1.16\"></r>؛</s> <s n=\"(b)\"><b>يمضي</b>، <b>ينصرف</b>؛ مجازيًا: <b>يزول</b>، <b>يعبر</b>: <r v=\"1Cor.7.31\"></r>؛ الصيغة الوسطى، <r v=\"1John.2.8\"></r>، <r v=\"1John.2.17\"></r>.†</s> </s>","en":"<f><o>παρ-άγω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5674\">עבר</h>;]</e> </et> <s n=\"1.\">trans., <b>to lead by</b>, <b>lead aside</b>, <b>lead into</b>, <b>lead forward</b>, etc.</s> <s n=\"2.\">Intrans., <s n=\"(a)\"><b>to pass by</b>: <r v=\"Matt.9.9\"></r>, <r v=\"Matt.9.27\"></r> <r v=\"Matt.20.30\"></r>, <r v=\"Mark.2.14\"></r> <r v=\"Mark.15.21\"></r>, <r v=\"John.8.59\"></r> R, txt., <r v=\"John.9.1\"></r>; seq. <g>παρό</g>, c. acc., <r v=\"Mark.1.16\"></r>;</s> <s n=\"(b)\"><b>to go away</b>, <b>depart</b>; metaph., <b>to pass away</b>: <r v=\"1Cor.7.31\"></r>; mid., <r v=\"1John.2.8\"></r>, <r v=\"1John.2.17\"></r>.†</s> </s>"},"G3806":{"l":"πάθος","o":3,"ar":"<f><o>πάθος</o>، <g>-ους, τό</g></f> <s n=\"1.\"><b>ما يصيب المرء</b>، <b>ما يقاسيه</b>.</s> <s n=\"2.\"><b>انفعال</b> أو <b>هوى</b> (خاصةً الانفعال العنيف)، <b>شهوة</b>، <b>رغبة جامحة</b>؛ وفي العهد الجديد دائمًا بالمعنى الرديء: <r v=\"Col.3.5\"></r>؛ <g>π. ἀτιμίας</g>، <r v=\"Rom.1.26\"></r>؛ <g>π. ἐπιθυμίας</g>، <r v=\"1Thess.4.5\"></r>.†</s>","en":"<f><o>πάθος</o>, <g>-ους, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>πάσχω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Job.30.31\"></r> (<h n=\"H60\">אֵבֶל</h>), <r v=\"Prov.25.20\"></r>, and very freq. in IV Mac (<r v=\"4Macc.1.1\"></r> ff., al.)*;]</e> <e t=\"derivation\">like <g>πάθημα</g>;</e> </et> <s n=\"1.\"><b>that which befalls one</b>, <b>that which one suffers</b>.</s> <s n=\"2.\"><b>a passive emotion</b> or <b>affection</b> (esp. of violent emotion), <b>a passion</b>, <b>passionate desire</b>; in NT always in bad sense: <r v=\"Col.3.5\"></r>; <g>π. ἀτιμίας</g>, <r v=\"Rom.1.26\"></r>; <g>π. ἐπιθυμίας</g>, <r v=\"1Thess.4.5\"></r>.†</s> <sy><i>SYN.</i>: <g>π.</g> = <g>πάθημα</g>, exc. that <g>πάθημα</g> is the more concrete and particular. In NT usage, <g>π.</g> represents the passive, ungoverned aspect of evil desire, as opp. to <g>ἐπιθυμία</g>, which is the active and also the more comprehensive term (v. Tr., <i>Syn.</i>, lxxxvii); cf. also <g>ὄρεξις</g>.</sy>"},"G3843":{"l":"πάντως","o":8,"ar":"<f><o>πάντως</o>،</f> ظرف <s><b>تمامًا</b>، <b>على كل حال</b>؛ <s n=\"(a)\">بدون نفي: <r v=\"1Cor.16.12\"></r>؛ وخاصةً في التوكيدات القوية: <b>حتمًا</b>، <b>على أية حال</b>: <r v=\"Luke.4.23\"></r>، <r v=\"Acts.21.22\"></r>، <r v=\"Acts.28.4\"></r>، <r v=\"1Cor.9.10\"></r>؛</s> <s n=\"(b)\">مع النفي، في نفي تام: <r v=\"Rom.3.9\"></r>؛ وفي نفي جزئي: <r v=\"1Cor.5.10\"></r>.†</s> </s>","en":"<f><o>πάντως</o>,</f> adv. <et> <e t=\"derivation\">(&lt; <g>πάς</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"2Kgs.5.11\"></r> (v. Thackeray, <i>Gr.</i>, 47), <r v=\"Tob.14.8\"></r>, al.;]</e> </et> <s><b>altogether</b>, <b>by all means</b>; <s n=\"(a)\">without neg. (from Hdt. on): <r v=\"1Cor.16.12\"></r>; esp. in strong affirmations, <b>surely</b>, <b>at all events</b>: <r v=\"Luke.4.23\"></r>, <r v=\"Acts.21.22\"></r> <r v=\"Acts.28.4\"></r>, <r v=\"1Cor.9.10\"></r>;</s> <s n=\"(b)\">c. neg. (so always in Hom.), in a complete negation: <r v=\"Rom.3.9\"></r>; in a partial negation (Bl., § 75, 7), <r v=\"1Cor.5.10\"></r>.†</s> </s>"},"G3876":{"l":"παρακοή","o":3,"ar":"<f>* <o>παρ-ακοή</o>، <g>-ῆς, ἡ</g>،</f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>سوء السماع</b>.</s> <s n=\"2.\">ثم، بوصفه نتيجة لعدم الإصغاء: <b>معصية</b>: <r v=\"Rom.5.19\"></r>، <r v=\"2Cor.10.6\"></r>، <r v=\"Heb.2.2\"></r> (قارن <g>παρακούω</g>).†</s>","en":"<f>* <o>παρ-ακοή</o>, <g>-ῆς, ἡ</g>,</f> <s n=\"1.\"><b>a hearing amiss</b> (Plat.).</s> <s n=\"2.\">Later, as following inattention, <b>disobedience</b>: <r v=\"Rom.5.19\"></r>, <r v=\"2Cor.10.6\"></r>, <r v=\"Heb.2.2\"></r> (cf. <g>παρακούω</g>, and v. Tr., <i>Syn.</i>, § lxvi).†</s>"},"G3897":{"l":"παραπλήσιος","o":1,"ar":"<f>* <o>παρα-πλήσιος</o>، <g>-α, -ον</g> (وأيضًا <g>-ος, -ον</g>)،</f> <s><b>مقارب</b>، <b>شبيه جدًّا</b>. والمحايد <g>-ον</g> ظرفًا = <g>ίως</g>: <b>على نحو قريب الشبه</b>: مع القابل: <r v=\"Phil.2.27\"></r>.†</s>","en":"<f>* <o>παρα-πλήσιος</o>, <g>-α, -ον</g> (Hdt., Plat., al.; also <g>-ος, -ον</g>, Thuc., Polyb.),</f> <s><b>coming near</b>, <b>nearly resembling</b>. Neut. <g>-ον</g>, adverbially, = <g>ίως</g>, <b>in a way nearly resembling</b>: c. dat., <r v=\"Phil.2.27\"></r>.†</s>"},"G3852":{"l":"παραγγελία","o":5,"ar":"<f>* <o>παρ-αγγελία</o>، <g>-ας, ἡ</g></f> <s><b>وصية</b>، <b>تكليف</b>، <b>أمر</b>: <r v=\"Acts.5.28\"></r>، <r v=\"Acts.16.24\"></r>، <r v=\"1Thess.4.2\"></r>، <r v=\"1Tim.1.5\"></r>، <r v=\"1Tim.1.18\"></r>. (في اليونانية الكلاسيكية: عن الأمر العسكري.)†</s>","en":"<f>* <o>παρ-αγγελία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>παραγγέλλω</g>),</e> </et> <s><b>an instruction</b>, <b>charge</b>, <b>command</b>: <r v=\"Acts.5.28\"></r> <r v=\"Acts.16.24\"></r>, <r v=\"1Thess.4.2\"></r>, <r v=\"1Tim.1.5\"></r>, <r v=\"1Tim.1.18\"></r>. (In Xen., Polyb., of a military order.)†</s>"},"G3824":{"l":"παλινγενεσία","o":2,"ar":"<f>*† <o>παλινγενεσία</o>، <g>-ας, ἡ</g></f> <s><b>ولادة جديدة</b>، <b>تجديد</b>، <b>استعادة</b>، <b>ميلاد ثانٍ</b>؛ <s n=\"(a)\">عن الأشخاص، عن التجديد الروحي: <g>διὰ λουτροῦ παλινγενεστίας</g> (مضاف إليه وصفي)، <r v=\"Titus.3.5\"></r>؛</s> <s n=\"(b)\">عن العالم (تجديد الكون)، <r v=\"Matt.19.28\"></r>.†</s> </s>","en":"<f>*† <o>παλινγενεσία</o> (Rec. <g>παλιγγ-</g>), <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>πάλιν</g>, <g>γένεσις</g>),</e> </et> <s><b>new birth</b>, <b>renewal</b>, <b>restoration</b>, <b>regeneration</b>; <s n=\"(a)\">of persons (Plut., Phil., al.), of spiritual regeneration, <g>διὰ λουτροῦ παλινγενεστίας</g> (gen. attr., v. Ellic., in l.), <r v=\"Titus.3.5\"></r>;</s> <s n=\"(b)\">of the world, as in Stoics, Jewish Apocal., al. (v. Dalman, <i>Words</i>, 177 ff.), <r v=\"Matt.19.28\"></r>.†</s> </s>"},"G3803":{"l":"παγίς","o":5,"ar":"<f><o>παγίς</o>، <g>-ίδος, ἡ</g></f> <s>بدلاً من <g>πάγη</g> في الشعر وعند المتأخرين: <b>فخّ</b>، <b>شَرَك</b>؛ مجازيًا: <r v=\"Luke.21.35\"></r>، <r v=\"Rom.11.9\"></r> <i>(السبعينية)</i>، <r v=\"1Tim.3.7\"></r>، <r v=\"1Tim.6.9\"></r>، <r v=\"2Tim.2.26\"></r>.†</s>","en":"<f><o>παγίς</o>, <g>-ίδος, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>πήγνυμι</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H6341\">פַּח</h>, <h n=\"H4170\">מוֹקֵשׁ</h>, <h n=\"H7568\">רֶשֶׁת</h>, etc.;]</e> </et> <s>poët. (Aristoph., al.) and late for <g>πάγη</g>, <b>a trap</b>, <b>snare</b>; metaph. (as also in cl.): <r v=\"Luke.21.35\"></r>, <r v=\"Rom.11.9\"></r><i>(LXX)</i>, <r v=\"1Tim.3.7\"></r> <r v=\"1Tim.6.9\"></r>, <r v=\"2Tim.2.26\"></r>.†</s>"},"G3854":{"l":"παραγίνομαι","o":37,"ar":"<f><o>παρα-γίνομαι</o></f> <s n=\"1.\"><b>كان بجانب</b> أو <b>كان حاضرًا قريبًا</b>، ومن ثم <b>وقف إلى جانب</b>، <b>ساند، نصر</b>: مع القابل للشخص، <r v=\"2Tim.4.16\"></r>.</s> <s n=\"2.\"><b>جاء</b>، <b>أقبل</b>، <b>وصل</b> (وكثيرًا عند الكتّاب المتأخرين): مطلقًا، <r v=\"Luke.14.21\"></r> <r v=\"Luke.19.16\"></r>، <r v=\"John.3.23\"></r>، <r v=\"Acts.5.21\"></r>، <r v=\"Acts.5.22\"></r>، <r v=\"Acts.5.25\"></r> <r v=\"Acts.9.39\"></r> <r v=\"Acts.10.32\"></r>، <r v=\"Acts.10.33\"></r> <r v=\"Acts.11.23\"></r> <r v=\"Acts.14.27\"></r> <r v=\"Acts.17.10\"></r> <r v=\"Acts.18.27\"></r> <r v=\"Acts.21.18\"></r> <r v=\"Acts.23.16\"></r>، <r v=\"Acts.23.35\"></r> <r v=\"Acts.24.17\"></r>، <r v=\"Acts.24.24\"></r> <r v=\"Acts.25.7\"></r> <r v=\"Acts.28.21\"></r>، <r v=\"1Cor.16.3\"></r>؛ يليه <g>εἰς</g>، <r v=\"John.8.2\"></r>، <r v=\"Acts.9.26\"></r> <r v=\"Acts.15.4\"></r>؛ <g>ἐπί</g> مع المنصوب، <r v=\"Luke.22.52\"></r>؛ <g>πρός</g> مع المنصوب، <r v=\"Luke.7.4\"></r>، <r v=\"Luke.7.20\"></r> <r v=\"Luke.8.19\"></r>، <r v=\"Acts.20.18\"></r>؛ وكذلك يليه <g>ἐκ</g>، <r v=\"Luke.11.6\"></r>؛ <g>παρά</g> مع المضاف إليه، <r v=\"Mark.14.43\"></r>؛ <g>ἀπὸ . . . εἰς</g>، <r v=\"Matt.2.1\"></r>، <r v=\"Acts.13.14\"></r>؛ <g>ἀπὸ . . . ἐπὶ . . . πρός</g>، <r v=\"Matt.3.13\"></r>؛ عن معلّم يظهر علانيةً أمام الناس: <r v=\"Matt.3.1\"></r>، <r v=\"Luke.12.51\"></r>، <r v=\"Heb.9.11\"></r>.†</s>","en":"<f><o>παρα-γίνομαι</o></f> <et> <e t=\"derivation\">(Ion. and late for <g>-γίγν-</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H935\">בּוֹא</h>;]</e> </et> <s n=\"1.\"><b>to be beside</b> or <b>at hand</b> (Hom., Hdt., al.), hence, <b>to stand by</b>, <b>support</b> (Æsch., Thuc., al.): c. dat. pers., <r v=\"2Tim.4.16\"></r>.</s> <s n=\"2.\"><b>to come</b>, <b>come up</b>, <b>arrive</b> (Hdt., Xen., al., and freq. in later writers; v. MM, xviii; Thackeray, <i>Gr.</i>, 267<i>2</i>): absol., <r v=\"Luke.14.21\"></r> <r v=\"Luke.19.16\"></r>, <r v=\"John.3.23\"></r>, <r v=\"Acts.5.21\"></r>, <r v=\"Acts.5.22\"></r>, <r v=\"Acts.5.25\"></r> <r v=\"Acts.9.39\"></r> <r v=\"Acts.10.32\"></r>, <r v=\"Acts.10.33\"></r> <r v=\"Acts.11.23\"></r> <r v=\"Acts.14.27\"></r> <r v=\"Acts.17.10\"></r> <r v=\"Acts.18.27\"></r> <r v=\"Acts.21.18\"></r> <r v=\"Acts.23.16\"></r>, <r v=\"Acts.23.35\"></r> <r v=\"Acts.24.17\"></r>, <r v=\"Acts.24.24\"></r> <r v=\"Acts.25.7\"></r> <r v=\"Acts.28.21\"></r>, <r v=\"1Cor.16.3\"></r>; seq. <g>εἰς</g>, <r v=\"John.8.2\"></r>, <r v=\"Acts.9.26\"></r> <r v=\"Acts.15.4\"></r>; <g>ἐπί</g>, c. acc., <r v=\"Luke.22.52\"></r>; <g>πρός</g>, c. acc., <r v=\"Luke.7.4\"></r>, <r v=\"Luke.7.20\"></r> <r v=\"Luke.8.19\"></r>, <r v=\"Acts.20.18\"></r>; id. seq. <g>ἐκ</g>, <r v=\"Luke.11.6\"></r>; <g>παρά</g>, c. gen., <r v=\"Mark.14.43\"></r>; <g>ἀπὸ . . . εἰς</g>, <r v=\"Matt.2.1\"></r>, <r v=\"Acts.13.14\"></r>; <g>ἀπὸ . . . ἐπὶ . . . πρός</g>, <r v=\"Matt.3.13\"></r>; of a teacher coming forward in public: <r v=\"Matt.3.1\"></r>, <r v=\"Luke.12.51\"></r>, <r v=\"Heb.9.11\"></r>.†</s>"},"G3800":{"l":"ὀψώνιον","o":4,"ar":"<f>**† <o>ὄψώνιον</o>، <g>-ου, τό</g></f> <s n=\"1.\"><b>مؤونة</b>، <b>نفقة المؤونة</b>، <b>أجرة الجنود، جراية</b>: <r v=\"Luke.3.14\"></r>، <r v=\"1Cor.9.7\"></r>.</s> <s n=\"2.\">عمومًا: <b>أجرة</b>، <b>أجر</b>: <r v=\"2Cor.11.8\"></r>؛ <g>ὄ. τῆς ἁμαρτίας</g>، <r v=\"Rom.6.23\"></r>.†</s>","en":"<f>**† <o>ὄψώνιον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>ὄψον</g>—v.s. <g>ὀψάριον</g>—and <g>ὠνέομαι</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"1Esd.4.56\"></r>, <r v=\"1Macc.3.28\"></r> <r v=\"1Macc.14.32\"></r>*;]</e> </et> <s n=\"1.\"><b>provisions</b>, <b>provision-money</b>, <b>soldiers' pay</b>: <r v=\"Luke.3.14\"></r>, <r v=\"1Cor.9.7\"></r>.</s> <s n=\"2.\">Generally, <b>wages</b>, <b>hire</b>: <r v=\"2Cor.11.8\"></r>; <g>ὄ. τῆς ἁμαρτίας</g>, <r v=\"Rom.6.23\"></r> (v. Deiss, <i>BS</i>, 148, 266).†</s>"},"G3810":{"l":"παιδευτής","o":2,"ar":"<f><o>παιδευτής</o>، <g>-οῦ, ὁ</g></f> <s n=\"1.\">أصلاً: <b>معلّم</b>، <b>مهذِّب</b>: <r v=\"Rom.2.20\"></r>.</s> <s n=\"2.\"><b>مؤدِّب</b>، <b>من يؤدِّب</b> (قارن <r v=\"Hos.5.2\"></r>): <r v=\"Heb.12.9\"></r>.†</s>","en":"<f><o>παιδευτής</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>παιδεύω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Hos.5.2\"></r> (<h n=\"H4148\">מוּסָר</h>), <r v=\"Sir.37.19\"></r>, <r v=\"4Macc.5.34\"></r> <r v=\"4Macc.9.6\"></r>*;]</e> </et> <s n=\"1.\">prop., <b>a teacher</b>, <b>instructor</b>: <r v=\"Rom.2.20\"></r>.</s> <s n=\"2.\"><b>a corrector</b>, <b>one who disciplines</b> (cf. <r v=\"Hos.5.2\"></r>): <r v=\"Heb.12.9\"></r>.†</s>"},"G3877":{"l":"παρακολουθέω","o":4,"ar":"<f>** <o>παρ-ακολουθέω</o>، <g>-ῶ</g>،</f> <s>مع القابل، <b>تبع عن قرب</b>، <b>رافق</b>. مجازيًا، بمعانٍ مختلفة، <s n=\"(a)\"><b>نتج عن، تبع</b>: <r v=\"Mark.16.17\"></r>؛</s> <s n=\"(b)\"><b>تتبّع</b>، <b>تقصّى</b>، <b>فحص</b>: <r v=\"Luke.1.3\"></r>؛</s> <s n=\"(c)\"><b>اتّبع</b> قاعدةً للسلوك: <r v=\"1Tim.4.6\"></r>، <r v=\"2Tim.3.10\"></r>.†</s> </s>","en":"<f>** <o>παρ-ακολουθέω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.8.11\"></r> <r v=\"2Macc.9.27\"></r> R*;]</e> </et> <s>c. dat., <b>to follow closely</b>, <b>accompany</b>. Metaph., in various senses, <s n=\"(a)\"><b>to result</b>: <r v=\"Mark.16.17\"></r>;</s> <s n=\"(b)\"><b>to follow up</b>, <b>trace</b>, <b>investigate</b>: <r v=\"Luke.1.3\"></r> (so freq. in cl.);</s> <s n=\"(c)\"><b>to follow</b> as a standard of conduct: <r v=\"1Tim.4.6\"></r>, <r v=\"2Tim.3.10\"></r>. (For exx. from <g>π.</g>, v. MM, xviii.)†</s> </s>"},"G3866":{"l":"παραθήκη","o":3,"ar":"<f><o>παρα-θήκη</o>، <g>-ης, ἡ</g></f> <s><b>وديعة</b> أو <b>أمانة</b>: <r v=\"1Tim.6.20\"></r>، <r v=\"2Tim.1.12\"></r>، <r v=\"2Tim.1.14\"></r>.†</s>","en":"<f><o>παρα-θήκη</o>, <g>-ης, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>παρατίθημι</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Lev.6.2\"></r>, <r v=\"Lev.6.4\"></r> (<r v=\"Lev.5.21\"></r>, <r v=\"Lev.6.23\"></r>) (<h n=\"H6487\">פִּקָּדוֹן</h>), and in <r v=\"Tob.10.13\"></r>, <r v=\"2Macc.3.10\"></r>, <r v=\"2Macc.3.15\"></r>, v.l. for <g>παρακαταθήκη</g> (q.v.)*;]</e> </et> <s><b>a deposit</b> or <b>trust</b>: <r v=\"1Tim.6.20\"></r>, <r v=\"2Tim.1.12\"></r>, <r v=\"2Tim.1.14\"></r> (for exx. of this form, v. MM, <i>Exp.</i>, iii, xviii).†</s>"},"G3814":{"l":"παιδίσκη","o":13,"ar":"<f><o>παιδίσκη</o>، <g>-ης, ἡ</g>،</f> <s n=\"1.\"><b>فتاة</b>، <b>صبيّة</b> (<h n=\"H5291\">נַעֲרָה</h>، <r v=\"Ruth.4.12\"></r>).</s> <s n=\"2.\">في الاستعمال الدارج: <b>جارية</b>، <b>أَمَة، خادمة</b>: <r v=\"Matt.26.69\"></r>، <r v=\"Mark.14.66\"></r>، <r v=\"Mark.14.69\"></r>، <r v=\"Luke.12.45\"></r> <r v=\"Luke.22.56\"></r>، <r v=\"John.18.17\"></r>، <r v=\"Acts.12.13\"></r> <r v=\"Acts.16.16\"></r>؛ عن هاجر، <r v=\"Gal.4.22\"></r>، <r v=\"Gal.4.23\"></r>، <r v=\"Gal.4.30\"></r><i>(السبعينية)</i>؛ والمعنى نفسه مجازيًا، <r v=\"Gal.4.31\"></r>.†</s>","en":"<f><o>παιδίσκη</o>, <g>-ης, ἡ</g>,</f> <et> <e t=\"derivation\">dimin, of <g>παῖς</g>,</e> <e t=\"septuagint\">[in LXX for <h n=\"H8198\">שִׁפְחָה</h>, <h n=\"H519\">אָמָה</h>, etc.;]</e> </et> <s n=\"1.\"><b>a young girl</b>, <b>a maiden</b> (<h n=\"H5291\">נַעֲרָה</h>, <r v=\"Ruth.4.12\"></r>).</s> <s n=\"2.\">Colloq., <b>a young female slave</b>, <b>a maid-servant</b> (v. Kennedy, <i>Sources</i>, 40 f.; Deiss., <i>LAE</i>, 186, 332<i>2</i>): <r v=\"Matt.26.69\"></r>, <r v=\"Mark.14.66\"></r>, <r v=\"Mark.14.69\"></r>, <r v=\"Luke.12.45\"></r> <r v=\"Luke.22.56\"></r>, <r v=\"John.18.17\"></r>, <r v=\"Acts.12.13\"></r> <r v=\"Acts.16.16\"></r>; of Hagar, <r v=\"Gal.4.22\"></r>, <r v=\"Gal.4.23\"></r>, <r v=\"Gal.4.30\"></r><i>(LXX)</i>; id., metaph., <r v=\"Gal.4.31\"></r>.†</s> <sy><i>SYN.</i>: v.s. <g>παῖς</g>.</sy>"},"G3862":{"l":"παράδοσις","o":13,"ar":"<f><o>παρά-δοσις</o>، <g>-εως, ἡ</g></f> <s n=\"1.\"><b>تسليم</b>، <b>نقل</b>، <b>تناقل</b> (في اليونانية الكلاسيكية والسبعينية).</s> <s n=\"2.\"><b>تقليد</b> (تسليم) التعليم؛ وكنايةً عن التعليم نفسه: <r v=\"Matt.15.2\"></r>، <r v=\"Matt.15.3\"></r>، <r v=\"Matt.15.6\"></r>، <r v=\"Mark.7.3\"></r> وما يليه، <r v=\"1Cor.11.2\"></r>، <r v=\"Gal.1.14\"></r>، <r v=\"Col.2.8\"></r>، <r v=\"2Thess.2.15\"></r> <r v=\"2Thess.3.9\"></r>.†</s>","en":"<f><o>παρά-δοσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>παραδίδωμι</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Ezra.7.26\"></r> (<h n=\"H612\">אֱסוּר</h>), <r v=\"Jer.32.4\"></r> (<h n=\"H5414\">נתן</h> ni.), <r v=\"Jer.34.2\"></r>*;]</e> </et> <s n=\"1.\"><b>a handing down</b> or <b>over</b>, <b>transfer</b>, <b>transmission</b> (Arist., Polyb., al., LXX).</s> <s n=\"2.\"><b>tradition</b> of doctrine (Plat., Epict., al.); by meton., of the doctrine itself : <r v=\"Matt.15.2\"></r>, <r v=\"Matt.15.3\"></r>, <r v=\"Matt.15.6\"></r>, <r v=\"Mark.7.3\"></r> ff., <r v=\"1Cor.11.2\"></r>, <r v=\"Gal.1.14\"></r>, <r v=\"Col.2.8\"></r>, <r v=\"2Thess.2.15\"></r> <r v=\"2Thess.3.9\"></r>.†</s>"},"G3848":{"l":"παραβάτης","o":5,"ar":"<f>** <o>παρα-βάτης</o>، <g>-ου, ὁ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>من يقف بجانب</b>، <b>المحارب الواقف بجوار سائق المركبة</b> (قارن <g>παραβαίνω</g>، 1).</s> <s n=\"2.\"><b>متعدٍّ، كاسر (للناموس)</b>: <r v=\"Gal.2.18\"></r>، <r v=\"Jas.2.9\"></r>؛ <g>π. νόμου</g> (متعدّي الناموس)، <r v=\"Rom.2.25\"></r>، <r v=\"Rom.2.27\"></r>، <r v=\"Jas.2.11\"></r>.†</s>","en":"<f>** <o>παρα-βάτης</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>παραβαίνω</g>),</e> <e t=\"septuagint\">[in Sm.: <r v=\"Ps.17.4\"></r> <r v=\"Ps.139.19\"></r>, <r v=\"Jer.6.28\"></r>*;]</e> </et> <s n=\"1.\"><b>one who stands beside</b>, <b>the warrior who stands by the charioteer</b> (cf. <g>παραβαίνω</g>, 1).</s> <s n=\"2.\"><b>a transgressor</b> (Æsch., <g>παρβάτης</g>): <r v=\"Gal.2.18\"></r>, <r v=\"Jas.2.9\"></r>; <g>π. νόμου</g>, <r v=\"Rom.2.25\"></r>, <r v=\"Rom.2.27\"></r>, <r v=\"Jas.2.11\"></r>.†</s>"},"G3888":{"l":"παραμυθέομαι","o":4,"ar":"<f>** <o>παρα-μυθέομαι</o>، <g>-οῦμαι</g>،</f> <s n=\"1.\"><b>يشجّع</b>، <b>يحثّ</b>.</s> <s n=\"2.\"><b>يعزّي</b>، <b>يُسلّي</b>: مع منصوب الشخص، <r v=\"John.11.31\"></r>، <r v=\"1Thess.2.11\"></r> <r v=\"1Thess.5.14\"></r>؛ والاستعمال نفسه يليه <g>περί</g>، <r v=\"John.11.19\"></r>.†</s>","en":"<f>** <o>παρα-μυθέομαι</o>, <g>-οῦμαι</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.15.9\"></r> (Sm.<i>8</i>)*;]</e> </et> <s n=\"1.\"><b>to encourage</b>, <b>exhort</b>.</s> <s n=\"2.\"><b>to comfort</b>, <b>console</b>: c. acc. pers., <r v=\"John.11.31\"></r>, <r v=\"1Thess.2.11\"></r> <r v=\"1Thess.5.14\"></r>; id. seq. <g>περί</g>, <r v=\"John.11.19\"></r>.†</s> <sy><i>SYN.</i>: <g>παρακαλέω</g>.</sy>"},"G3858":{"l":"παραδέχομαι","o":6,"ar":"<f><o>παρα-δέχομαι</o>،</f> <s><b>يقبل</b>، <b>يرتضي</b>؛ <s n=\"(a)\">عن الأشياء: <r v=\"Mark.4.20\"></r>، <r v=\"Acts.15.4\"></r> <r v=\"Acts.16.21\"></r> <r v=\"Acts.22.18\"></r>، <r v=\"1Tim.5.19\"></r>؛</s> <s n=\"(b)\">عن الأشخاص: <r v=\"Heb.12.6\"></r><i>(السبعينية)</i>.†</s> </s>","en":"<f><o>παρα-δέχομαι</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Exod.23.1\"></r> (<h n=\"H5375\">נשׂא</h>), <r v=\"Prov.3.12\"></r> (<h n=\"H7521\">רצה</h>), <r v=\"2Macc.4.22\"></r> R, <r v=\"3Macc.7.12\"></r>*;]</e> </et> <s><b>to receive</b>, <b>admit</b>; <s n=\"(a)\">of things: <r v=\"Mark.4.20\"></r>, <r v=\"Acts.15.4\"></r> <r v=\"Acts.16.21\"></r> <r v=\"Acts.22.18\"></r>, <r v=\"1Tim.5.19\"></r>;</s> <s n=\"(b)\">of persons: <r v=\"Heb.12.6\"></r><i>(LXX)</i>.†</s> </s>"},"G3887":{"l":"παραμένω","o":4,"ar":"<f><o>παρα-μένω</o>،</f> <s><b>يبقى بجانب</b> أو <b>قريبًا من، يثبت، يدوم</b>: <r v=\"Heb.7.23\"></r>، <r v=\"Jas.1.25\"></r>؛ عن البقاء على قيد الحياة، <r v=\"1Cor.16.6\"></r>، <r v=\"Phil.1.25\"></r> (قارن <g>συμ-παραμένω</g>).†</s>","en":"<f><o>παρα-μένω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Prov.12.7\"></r>, <r v=\"Dan.11.17\"></r> (<h n=\"H5975\">עמד</h>), etc.;]</e> </et> <s><b>to remain beside</b> or <b>near</b>: <r v=\"Heb.7.23\"></r>, <r v=\"Jas.1.25\"></r>; of remaining alive, <r v=\"1Cor.16.6\"></r> (WH, <g>κατα-</g>), <r v=\"Phil.1.25\"></r> (cf. <g>συμ-παραμένω</g>).†</s>"},"G3811":{"l":"παιδεύω","o":13,"ar":"<f><o>παιδεύω</o></f> <s n=\"1.\">كما في الكلاسيكية: <b>يربّي الأولاد</b>، ومن ثمّ عمومًا: <b>يعلّم</b>، <b>يهذّب</b>: <r v=\"Acts.7.22\"></r>، <r v=\"Acts.22.3\"></r>، <r v=\"1Tim.1.20\"></r>، <r v=\"Titus.2.12\"></r>.</s> <s n=\"2.\">كما في السبعينية (<r v=\"Ps.6.2\"></r>، <r v=\"Prov.19.18\"></r>، <r v=\"Wis.3.5\"></r>، وفي مواضع أخرى): <b>يؤدّب</b>، <b>يقوّم</b>، <b>يعاقب</b>: <r v=\"Luke.23.16\"></r>، <r v=\"Luke.23.22\"></r>، <r v=\"2Tim.2.25\"></r>، <r v=\"Heb.12.7\"></r>، <r v=\"Heb.12.10\"></r>؛ عن التأديب الإلهي، <r v=\"1Cor.11.32\"></r>، <r v=\"2Cor.6.9\"></r>، <r v=\"Heb.12.6\"></r>، <r v=\"Rev.3.19\"></r>.†</s>","en":"<f><o>παιδεύω</o></f> <et> <e t=\"derivation\">(&lt; <g>παίς</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3256\">יסר</h>;]</e> </et> <s n=\"1.\">as in cl., <b>to train children</b>, hence, generally, <b>to teach</b>, <b>instruct</b>: <r v=\"Acts.7.22\"></r> <r v=\"Acts.22.3\"></r>, <r v=\"1Tim.1.20\"></r>, <r v=\"Titus.2.12\"></r>.</s> <s n=\"2.\">As in LXX (<r v=\"Ps.6.2\"></r>, <r v=\"Prov.19.18\"></r>, <r v=\"Wis.3.5\"></r>, al., and for prob. ex. from <g>π.</g>, v. MM, xviii), <b>to chasten</b>, <b>correct</b>, <b>chastise</b>: <r v=\"Luke.23.16\"></r>, <r v=\"Luke.23.22\"></r>, <r v=\"2Tim.2.25\"></r>, <r v=\"Heb.12.7\"></r>, <r v=\"Heb.12.10\"></r>; of divine chastening, <r v=\"1Cor.11.32\"></r>, <r v=\"2Cor.6.9\"></r>, <r v=\"Heb.12.6\"></r>, <r v=\"Rev.3.19\"></r>.†</s> <sy><i>SYN.</i>: <g>διδάσκω</g>, q.v.</sy>"},"G3804":{"l":"πάθημα","o":16,"ar":"<f>* <o>πάθημα</o>، <g>-τος, τό</g></f> <s n=\"1.\"><b>ما يصيب الإنسان</b>، <b>ألم</b>، <b>ضيقة</b>: في الجمع، <r v=\"Rom.8.18\"></r>، <r v=\"2Cor.1.6\"></r>، <r v=\"2Cor.1.7\"></r>، <r v=\"Col.1.24\"></r>، <r v=\"2Tim.3.11\"></r>، <r v=\"Heb.2.10\"></r> <r v=\"Heb.10.32\"></r>، <r v=\"1Pet.5.9\"></r>؛ عن آلام المسيح: <g>τὰ εἰς Χ.</g>، <r v=\"1Pet.1.11\"></r>؛ <g>τ. Χριστσῦ</g>، <r v=\"1Pet.5.1\"></r>؛ وكذلك بوصفها آلامًا يشترك فيها المسيحيون، <r v=\"2Cor.1.5\"></r>، <r v=\"Phil.3.10\"></r>، <r v=\"1Pet.4.13\"></r>.</s> <s n=\"2.\"><b>انفعال</b>، <b>عاطفة</b>، <b>هوى</b>: <r v=\"Gal.5.24\"></r>؛ <g>τ. ἁμαρτιῶν</g>، <r v=\"Rom.7.5\"></r>.</s> <s n=\"3.\">بمعنى <g>τὸ πάσχειν</g>: <b>احتمال</b> أو <b>تألّم</b>: مع المضاف إليه المفعول، <r v=\"Heb.2.9\"></r>.†</s>","en":"<f>* <o>πάθημα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>πάσχω</g>), like <g>πάθος</g>,</e> </et> <s n=\"1.\"><b>that which befalls one</b>, <b>a suffering</b>, <b>affliction</b>: pl., <r v=\"Rom.8.18\"></r>, <r v=\"2Cor.1.6\"></r>, <r v=\"2Cor.1.7\"></r>, <r v=\"Col.1.24\"></r>, <r v=\"2Tim.3.11\"></r>, <r v=\"Heb.2.10\"></r> <r v=\"Heb.10.32\"></r>, <r v=\"1Pet.5.9\"></r>; of Christ's sufferings: <g>τὰ εἰς Χ.</g>, <r v=\"1Pet.1.11\"></r>; <g>τ. Χριστσῦ</g>, <r v=\"1Pet.5.1\"></r>; id. as shared by Christians, <r v=\"2Cor.1.5\"></r>, <r v=\"Phil.3.10\"></r>, <r v=\"1Pet.4.13\"></r>.</s> <s n=\"2.\"><b>a passive emotion</b>, <b>affection</b>, <b>passion</b>: <r v=\"Gal.5.24\"></r>; <g>τ. ἁμαρτιῶν</g>, <r v=\"Rom.7.5\"></r>.</s> <s n=\"3.\">= <g>τὸ πάσχειν</g>, <b>an enduring</b> or <b>suffering</b>: c. gen. obj., <r v=\"Heb.2.9\"></r>.†</s> <sy><i>SYN.</i>: v.s. <g>πάθος</g>.</sy>"},"G3847":{"l":"παράβασις","o":7,"ar":"<f><o>παρά-βασις</o>، <g>-εως, ἡ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>انحراف</b>، <b>حَيْدان</b>.</s> <s n=\"2.\">عند الكتّاب المتأخرين: <b>تخطٍّ</b>؛ ومجازيًا: <b>تعدٍّ، معصية</b>: <r v=\"Rom.4.15\"></r> <r v=\"Rom.5.14\"></r>، <r v=\"Heb.2.2\"></r> <r v=\"Heb.9.15\"></r>؛ <g>τ. νόμου</g>، <r v=\"Rom.2.23\"></r>؛ <g>ἐν π.</g>، <r v=\"1Tim.2.14\"></r>؛ <g>τ. παραβάσεων χάριν</g>، <r v=\"Gal.3.19\"></r>.</s>","en":"<f><o>παρά-βασις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>παραβαίνω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Ps.101.3\"></r> (<h n=\"H7750\">סֵטִים</h>), <r v=\"2Kgs.2.24\"></r> A, <r v=\"Wis.14.31\"></r>, <r v=\"2Macc.15.10\"></r>*;]</e> </et> <s n=\"1.\"><b>a going aside</b>, <b>a deviation</b> (Arist.).</s> <s n=\"2.\">In later writers, <b>an overstepping</b>; metaph., <b>transgression</b> (Plut., al.): <r v=\"Rom.4.15\"></r> <r v=\"Rom.5.14\"></r>, <r v=\"Heb.2.2\"></r> <r v=\"Heb.9.15\"></r>; <g>τ. νόμου</g>, <r v=\"Rom.2.23\"></r>; <g>ἐν π.</g>, <r v=\"1Tim.2.14\"></r>; <g>τ. παραβάσεων χάριν</g>, <r v=\"Gal.3.19\"></r>.</s> <sy><i>SYN.</i>: v.s. <g>ἁμαρτία</g>.</sy>"},"G3851":{"l":"παραβολεύομαι","o":1,"ar":"<f>*† <o>παρα-βολεύομαι</o></f> <s>= <g>παραβάλλομαι</g> في اليونانية الكلاسيكية (<r v=\"2Macc.14.38\"></r>)،</s> <s><b>يعرّض نفسه للخطر</b>، <b>يخاطر بحياته</b>: مع القابل للمتعلَّق، <g>τ. ψυχῇ</g>، <r v=\"Phil.2.30\"></r>.†</s>","en":"<f>*† <o>παρα-βολεύομαι</o></f> <s>= cl. <g>παραβάλλομαι</g> (<r v=\"2Macc.14.38\"></r>),</s> <s><b>to expose oneself to danger</b>, <b>hazard one's life</b>: c. dat. ref., <g>τ. ψυχῇ</g> (v. M, <i>Pr.</i>, 64), <r v=\"Phil.2.30\"></r> (Rec. <g>παραβουλ-</g>). Cited by Deiss., <i>LAE</i>, 84, 120.†</s>"},"G3835":{"l":"πανοῦργος","o":1,"ar":"<f><o>πανοῦργος</o>، <g>-ον</g>،</f> <s><b>مستعدّ لفعل أي شيء</b>؛ <s n=\"(a)\">(في الكلاسيكية غالبًا بالمعنى السيئ)، <b>محتال</b>، <b>ماكر</b>: <r v=\"2Cor.12.16\"></r>؛</s> <s n=\"(b)\">في السبعينية بالمعنى الحسن: <b>ماهر</b>، <b>حاذق</b> (<r v=\"Prov.13.1\"></r> <r v=\"Prov.28.2\"></r>).†</s> </s>","en":"<f><o>πανοῦργος</o>, <g>-ον</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6175\">עָרוּם</h>;]</e> </et> <s><b>ready to do anything</b>; <s n=\"(a)\">in cl., chiefly in bad sense, <b>knavish</b>, <b>crafty</b>: <r v=\"2Cor.12.16\"></r>;</s> <s n=\"(b)\">in good sense, <b>skilful</b>, <b>clever</b> (<r v=\"Prov.13.1\"></r> <r v=\"Prov.28.2\"></r>).†</s> </s>"},"G3813":{"l":"παιδίον","o":52,"ar":"<f><o>παιδίον</o>، <g>-ου, τό</g>،</f> <s><b>طفل صغير</b>، <b>صغير</b>: <r v=\"Matt.2.8\"></r>، <r v=\"Matt.2.9\"></r>، <r v=\"Matt.2.11\"></r> وما يليه، <r v=\"Luke.1.59\"></r>، <r v=\"Luke.1.66\"></r>، <r v=\"Luke.1.76\"></r>، <r v=\"Luke.1.80\"></r>، <r v=\"Luke.2.17\"></r>، <r v=\"Luke.2.27\"></r>، <r v=\"Luke.2.40\"></r>، <r v=\"John.16.21\"></r>، <r v=\"Heb.11.23\"></r>؛ عن أطفال أكبر سنًّا: <r v=\"Matt.18.2\"></r>، <r v=\"Matt.18.4\"></r>، <r v=\"Matt.18.5\"></r>، <r v=\"Mark.5.39-Mark.5.41\"></r>، <r v=\"Mark.7.30\"></r>، <r v=\"Mark.9.24\"></r>، <r v=\"Mark.9.36\"></r>، <r v=\"Luke.9.47\"></r>، <r v=\"Luke.9.48\"></r>، <r v=\"Luke.18.17\"></r>، <r v=\"John.4.49\"></r>؛ في الجمع: <r v=\"Matt.11.16\"></r>، <r v=\"Matt.14.21\"></r>، <r v=\"Matt.15.38\"></r>، <r v=\"Matt.18.3\"></r>، <r v=\"Matt.19.13\"></r>، <r v=\"Matt.19.14\"></r>، <r v=\"Mark.7.28\"></r>، <r v=\"Mark.10.13\"></r> وما يليه، <r v=\"Luke.7.32\"></r>، <r v=\"Luke.11.7\"></r>، <r v=\"Luke.18.16\"></r>، <r v=\"Heb.2.13\"></r>، <r v=\"Heb.2.14\"></r>. مجازيًا: <r v=\"1Cor.14.20\"></r>. في المخاطبة الودية بلغة دارجة («يا أولاد»، «يا فتيان»): <r v=\"John.21.5\"></r>، <r v=\"1John.2.13\"></r>، <r v=\"1John.2.18\"></r>، <r v=\"1John.3.7\"></r>.†</s>","en":"<f><o>παιδίον</o>, <g>-ου, τό</g>,</f> <et> <e t=\"derivation\">dimin, of <g>παῖς</g>,</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3206\">יֶלֶד</h>, also for <h n=\"H5288\">נַעַר</h>, <h n=\"H1121\">בֵּן</h>, etc., freq. in To in ref. to full-grown youth;]</e> </et> <s><b>a young child</b>, <b>a little one</b>: <r v=\"Matt.2.8\"></r>, <r v=\"Matt.2.9\"></r>, <r v=\"Matt.2.11\"></r>, ff., <r v=\"Luke.1.59\"></r>, <r v=\"Luke.1.66\"></r>, <r v=\"Luke.1.76\"></r>, <r v=\"Luke.1.80\"></r> <r v=\"Luke.2.17\"></r>, <r v=\"Luke.2.27\"></r>, <r v=\"Luke.2.40\"></r>, <r v=\"John.16.21\"></r>, <r v=\"Heb.11.23\"></r>; of older children, <r v=\"Matt.18.2\"></r>, <r v=\"Matt.18.4\"></r>, <r v=\"Matt.18.5\"></r>, <r v=\"Mark.5.39-Mark.5.41\"></r> <r v=\"Mark.7.30\"></r> <r v=\"Mark.9.24\"></r>, <r v=\"Mark.9.36\"></r>, <r v=\"Luke.9.47\"></r>, <r v=\"Luke.9.48\"></r> <r v=\"Luke.18.17\"></r>, <r v=\"John.4.49\"></r>; in pl., <r v=\"Matt.11.16\"></r> <r v=\"Matt.14.21\"></r> <r v=\"Matt.15.38\"></r> <r v=\"Matt.18.3\"></r> <r v=\"Matt.19.13\"></r>, <r v=\"Matt.19.14\"></r>, <r v=\"Mark.7.28\"></r> <r v=\"Mark.10.13\"></r> ff., <r v=\"Luke.7.32\"></r> <r v=\"Luke.11.7\"></r> <r v=\"Luke.18.16\"></r>, <r v=\"Heb.2.13\"></r>, <r v=\"Heb.2.14\"></r> Metaph., <r v=\"1Cor.14.20\"></r>. Colloq. in familiar address (as Eng. colloq., \"lads\"—v. M, <i>Pr.</i>, 170<i>n</i>—and Irish use of \"boys\"): <r v=\"John.21.5\"></r>, <r v=\"1John.2.13\"></r>, <r v=\"1John.2.18\"></r> <r v=\"1John.3.7\"></r>.†</s> <sy><i>SYN.</i>: v.s. <g>παῖς</g>.</sy>"},"G3837":{"l":"πανταχοῦ","o":7,"ar":"<f><o>πανταχοῦ</o>،</f> ظرف، <s>في كل مكان: <r v=\"Mark.1.28\"></r> <r v=\"Mark.16.20\"></r>، <r v=\"Luke.9.6\"></r>، <r v=\"Acts.17.30\"></r> <r v=\"Acts.24.3\"></r> <r v=\"Acts.28.22\"></r>، <r v=\"1Cor.4.17\"></r>.†</s>","en":"<f><o>πανταχοῦ</o>,</f> adv., <et> <e t=\"septuagint\">[in LXX: <r v=\"Isa.42.22\"></r> (<h n=\"H3637\">כֻּלָּם</h>)*;]</e> </et> <s>everywhere: <r v=\"Mark.1.28\"></r> <r v=\"Mark.16.20\"></r>, <r v=\"Luke.9.6\"></r>, <r v=\"Acts.17.30\"></r> <r v=\"Acts.24.3\"></r> <r v=\"Acts.28.22\"></r>, <r v=\"1Cor.4.17\"></r>.†</s>"},"G3815":{"l":"παίζω","o":1,"ar":"<f><o>παίζω</o></f> <s>أصلاً: <b>لعب كالطفل</b>، ومن ثمّ عمومًا: <b>لعب</b> (كالغناء والرقص): <r v=\"1Cor.10.7\"></r><i>(السبعينية)</i> (قارن <g>ἐμ-παίζω</g>).†</s>","en":"<f><o>παίζω</o></f> <et> <e t=\"derivation\">(&lt; <g>παῖς</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Gen.21.9\"></r> <r v=\"Gen.26.8\"></r>, <r v=\"Exod.32.6\"></r> (<h n=\"H6711\">צחק</h> pi.); and more freq. (<r v=\"Judg.16.25\"></r>, al.) for (<h n=\"H7832\">שׁחק</h> pi.;]</e> </et> <s>prop., <b>to play as a child</b>, hence, generally, <b>to play</b> (as with singing and dancing): <r v=\"1Cor.10.7\"></r><i>(LXX)</i> (cf. <g>ἐμ-παίζω</g>).†</s>"},"G3868":{"l":"παραιτέομαι","o":12,"ar":"<f><o>παρ-αιτέομαι</o>، <g>-οῦμαι</g>،</f> <s n=\"1.\"><b>طلب من</b> آخر، <b>التمس</b>: <r v=\"Mark.15.6\"></r>.</s> <s n=\"2.\"><b>استعفى، رفض</b>؛ <s n=\"(a)\">أصلاً، مع النفي: <b>توسّل</b> ألّا: <r v=\"Heb.12.19\"></r>؛</s> <s n=\"(b)\"><b>رفض</b>، <b>استعفى</b>، <b>تجنّب</b>: مع المنصوب، <r v=\"1Tim.4.7\"></r> <r v=\"1Tim.5.11\"></r>، <r v=\"2Tim.2.23\"></r>، <r v=\"Titus.3.10\"></r>، <r v=\"Heb.12.25\"></r>.</s> </s> <s n=\"3.\"><b>اعتذر</b>، <b>طلب أن يُعفى</b>، <b>أعفى</b>: <r v=\"Luke.14.18\"></r>، <r v=\"Luke.14.19\"></r> (قارن <r v=\"Heb.12.25\"></r>).†</s>","en":"<f><o>παρ-αιτέομαι</o>, <g>-οῦμαι</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H1245\">בּקשׁ</h> pi., etc.;]</e> </et> <s n=\"1.\"><b>to beg of</b> or <b>from</b> another: <r v=\"Mark.15.6\"></r> (Rec. <g>ὅνπερ ᾐτοῦντο</g>, v. Field, <i>Notes</i>, 43).</s> <s n=\"2.\"><b>to deprecate</b>; <s n=\"(a)\">prop., c. neg., <b>to entreat</b> that <b>not</b> (Thuc., al.): <r v=\"Heb.12.19\"></r>;</s> <s n=\"(b)\"><b>to refuse</b>, <b>decline</b>, <b>avoid</b>: o. acc., <r v=\"1Tim.4.7\"></r> <r v=\"1Tim.5.11\"></r>, <r v=\"2Tim.2.23\"></r>, <r v=\"Titus.3.10\"></r>, <r v=\"Heb.12.25\"></r> (EV; but v. Field, <i>Notes</i>, 234).</s> </s> <s n=\"3.\"><b>to beg off</b>, <b>ask to be excused</b>, <b>excuse</b> (Polyb., al.) : <r v=\"Luke.14.18\"></r>, <r v=\"Luke.14.19\"></r> (<r v=\"Heb.12.25\"></r>, Field, <i>Notes</i>, 234).†</s>"},"G3873":{"l":"παράκειμαι","o":2,"ar":"<f>** <o>παρά-κειμαι</o>،</f> <s><b>اضطجع بجانب</b>، <b>كان قريبًا</b>، <b>كان حاضرًا</b>: <r v=\"Rom.7.18\"></r>، <r v=\"Rom.7.21\"></r>.†</s>","en":"<f>** <o>παρά-κειμαι</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Jdt.3.2\"></r>, <r v=\"Jdt.3.3\"></r>, <r v=\"Sir.30.18\"></r> <r v=\"Sir.31.16\"></r>, <r v=\"Bel.1.14\"></r>, II, III Mac<i>5</i>*;]</e> </et> <s><b>to lie beside</b>, <b>be near</b>, <b>be present</b>: <r v=\"Rom.7.18\"></r>, <r v=\"Rom.7.21\"></r>.†</s>"},"G3821":{"l":"παλαιότης","o":1,"ar":"<f>* <o>παλαιότης</o>، <g>-ητος, ἡ</g></f> <s><b>عتق</b>: <g>γράμματος</g>، <r v=\"Rom.7.6\"></r>.†</s>","en":"<f>* <o>παλαιότης</o>, <g>-ητος, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>παλαιός</g>),</e> </et> <s><b>oldness</b>: <g>γράμματος</g>, <r v=\"Rom.7.6\"></r>.†</s>"},"G3880":{"l":"παραλαμβάνω","o":49,"ar":"<f><o>παρα-λαμβάνω</o>،</f> <s n=\"1.\">مع المنصوب للشيء، مثل <g>παραδέχομαι</g>، ومقابل <g>παραδίδωμι</g>: <b>تسلّم، قَبِل</b> من آخر: <r v=\"Col.4.17\"></r>، <r v=\"Heb.12.28\"></r>؛ عن الذهن، <r v=\"1Cor.11.23\"></r> <r v=\"1Cor.15.1\"></r>، <r v=\"1Cor.15.3\"></r>، <r v=\"Gal.1.9\"></r>، <r v=\"Phil.4.9\"></r>؛ مع المصدر، <r v=\"Mark.7.4\"></r>؛ يليه <g>παρά</g> مع المضاف إليه، <r v=\"Gal.1.12\"></r>، <r v=\"1Thess.2.13\"></r> <r v=\"1Thess.4.1\"></r>، <r v=\"2Thess.3.6\"></r>؛ <g>τ. Χριστόν</g>، <r v=\"Col.2.6\"></r>.</s> <s n=\"2.\">مع المنصوب للشخص: <b>أخذ إليه</b> أو <b>أخذ معه</b>: <r v=\"Matt.2.13\"></r>، <r v=\"Matt.2.14\"></r>، <r v=\"Matt.2.20\"></r>، <r v=\"Matt.2.21\"></r> <r v=\"Matt.17.1\"></r> <r v=\"Matt.26.37\"></r>، <r v=\"Mark.4.36\"></r> <r v=\"Mark.5.40\"></r> <r v=\"Mark.9.2\"></r> <r v=\"Mark.10.32\"></r>، <r v=\"Luke.9.10\"></r>، <r v=\"Luke.9.28\"></r> <r v=\"Luke.11.26\"></r> <r v=\"Luke.18.31\"></r> <r v=\"John.19.16\"></r>، <r v=\"Acts.15.39\"></r> <r v=\"Acts.23.18\"></r>؛ <g>γυναῖκα</g>، <r v=\"Matt.1.20\"></r>، <r v=\"Matt.1.24\"></r>؛ <g>μεθ’ ἑαυτοῦ</g>، <r v=\"Matt.12.45\"></r> <r v=\"Matt.18.16\"></r>، <r v=\"Mark.14.33\"></r>؛ يليه <g>εἰς</g>، <r v=\"Matt.4.5\"></r>، <r v=\"Matt.4.8\"></r> <r v=\"Matt.27.27\"></r>؛ <g>κατ’ ἰδίαν</g>، <r v=\"Matt.20.17\"></r>؛ الصيغة الوسطى، يليه <g>πρὸς ἐμαυτόν</g>، <r v=\"John.14.3\"></r>؛ المبني للمجهول، <r v=\"Matt.24.40\"></r>، <r v=\"Matt.24.41\"></r>، <r v=\"Luke.17.34-Luke.17.36\"></r>؛ اسم الفاعل مُقدَّمًا على أفعال أخرى، <r v=\"Acts.16.33\"></r> <r v=\"Acts.21.24\"></r>، <r v=\"Acts.21.26\"></r>، <r v=\"Acts.21.32\"></r>؛ مجازيًا، <r v=\"John.1.11\"></r>.†</s>","en":"<f><o>παρα-λαμβάνω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3947\">לקח</h>, also for <h n=\"H3423\">ירשׁ</h>, etc.;]</e> </et> <s n=\"1.\">c. acc. rei, like <g>παραδέχομαι</g>, correl. to <g>παραδίδωμι</g>, <b>to receive</b> from another: <r v=\"Col.4.17\"></r>, <r v=\"Heb.12.28\"></r>; of the mind, <r v=\"1Cor.11.23\"></r> <r v=\"1Cor.15.1\"></r>, <r v=\"1Cor.15.3\"></r>, <r v=\"Gal.1.9\"></r>, <r v=\"Phil.4.9\"></r>; c. inf., <r v=\"Mark.7.4\"></r>; seq. <g>παρά</g>, c. gen., <r v=\"Gal.1.12\"></r>, <r v=\"1Thess.2.13\"></r> <r v=\"1Thess.4.1\"></r>, <r v=\"2Thess.3.6\"></r>; <g>τ. Χριστόν</g> (Lft., in l.), <r v=\"Col.2.6\"></r>.</s> <s n=\"2.\">C. acc. pers., <b>to take to</b> or <b>with oneself</b>: <r v=\"Matt.2.13\"></r>, <r v=\"Matt.2.14\"></r>, <r v=\"Matt.2.20\"></r>, <r v=\"Matt.2.21\"></r> <r v=\"Matt.17.1\"></r> <r v=\"Matt.26.37\"></r>, <r v=\"Mark.4.36\"></r> <r v=\"Mark.5.40\"></r> <r v=\"Mark.9.2\"></r> <r v=\"Mark.10.32\"></r>, <r v=\"Luke.9.10\"></r>, <r v=\"Luke.9.28\"></r> <r v=\"Luke.11.26\"></r> <r v=\"Luke.18.31\"></r> <r v=\"John.19.16\"></r>, <r v=\"Acts.15.39\"></r> <r v=\"Acts.23.18\"></r>; <g>γυναῖκα</g>, <r v=\"Matt.1.20\"></r>, <r v=\"Matt.1.24\"></r>; <g>μεθ’ ἑαυτοῦ</g>, <r v=\"Matt.12.45\"></r> <r v=\"Matt.18.16\"></r>, <r v=\"Mark.14.33\"></r>; seq. <g>εἰς</g>, <r v=\"Matt.4.5\"></r>, <r v=\"Matt.4.8\"></r> <r v=\"Matt.27.27\"></r>; <g>κατ’ ἰδίαν</g>, <r v=\"Matt.20.17\"></r>; mid., seq. <g>πρὸς ἐμαυτόν</g>, <r v=\"John.14.3\"></r>; pass., <r v=\"Matt.24.40\"></r>, <r v=\"Matt.24.41\"></r>, <r v=\"Luke.17.34-Luke.17.36\"></r>; ptcp., prefixed to other verbs (Bl, § 74, 2), <r v=\"Acts.16.33\"></r> <r v=\"Acts.21.24\"></r>, <r v=\"Acts.21.26\"></r>, <r v=\"Acts.21.32\"></r>; metaph., <r v=\"John.1.11\"></r>.†</s>"},"G3863":{"l":"παραζηλόω","o":4,"ar":"<f>† <o>παρα-ζηλόω</o>، <g>-ῶ</g>،</f> <s><b>أغار، أثار الغيرة</b>: <r v=\"Rom.10.19\"></r><i>(السبعينية)</i> <r v=\"Rom.11.11\"></r>، <r v=\"Rom.11.14\"></r>، <r v=\"1Cor.10.22\"></r>.†</s>","en":"<f>† <o>παρα-ζηλόω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Deut.32.21\"></r>, <r v=\"1Kgs.14.22\"></r>, <r v=\"Ps.78.58\"></r> (<h n=\"H7065\">קנא</h> pi., hi.), <r v=\"Ps.37.1\"></r>, <r v=\"Ps.37.7\"></r>, <r v=\"Ps.37.8\"></r> (<h n=\"H2734\">חרה</h> hith.), <r v=\"Sir.30.3\"></r>*;]</e> </et> <s><b>to provoke to jealousy</b>: <r v=\"Rom.10.19\"></r><i>(LXX)</i> <r v=\"Rom.11.11\"></r>, <r v=\"Rom.11.14\"></r>, <r v=\"1Cor.10.22\"></r>.†</s>"},"G3853":{"l":"παραγγέλλω","o":32,"ar":"<f><o>παρ-αγγέλλω</o></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>ينقل رسالة</b>.</s> <s n=\"2.\"><b>يأمر</b>، <b>يوصي</b>: مع المصدر، <r v=\"Acts.15.5\"></r>؛ مع المنصوب للشيء، <r v=\"1Cor.11.17\"></r>، <r v=\"2Thess.3.4\"></r>، <r v=\"1Tim.4.11\"></r> <r v=\"1Tim.5.7\"></r>؛ يليه <g>ἵνα</g>، <r v=\"Mark.6.8\"></r>، <r v=\"2Thess.3.12\"></r>؛ مع القابل للشخص، <r v=\"Acts.17.30\"></r>، <r v=\"1Thess.4.11\"></r>؛ يليه <g>λέγων</g>، <r v=\"Matt.10.5\"></r>؛ مع مصدر الماضي البسيط، <r v=\"Matt.15.35\"></r>، <r v=\"Mark.8.6\"></r>، <r v=\"Luke.8.29\"></r>، <r v=\"Acts.10.42\"></r> <r v=\"Acts.16.18\"></r> (مضارع بمعنى الماضي البسيط)؛ ونفسه مع النفي، <g>μή</g>، <r v=\"Luke.5.14\"></r> <r v=\"Luke.8.56\"></r>، <r v=\"Acts.23.22\"></r>، <r v=\"1Cor.7.10\"></r>؛ مع مصدر المضارع، <r v=\"Acts.16.23\"></r>، <r v=\"2Thess.3.6\"></r>؛ ونفسه مع النفي، <g>μή</g>، <r v=\"Luke.9.21\"></r>، <r v=\"Acts.1.4\"></r> <r v=\"Acts.4.18\"></r> <r v=\"Acts.5.28\"></r>، <r v=\"Acts.5.40\"></r>، <r v=\"1Tim.1.3\"></r> <r v=\"1Tim.6.17\"></r>؛ مع المنصوب <g>τοῦτο</g> ويليه <g>ὅτι</g>، <r v=\"2Thess.3.10\"></r>؛ مع المنصوب والمصدر، <r v=\"Acts.23.30\"></r>، <r v=\"2Thess.3.6\"></r>، <r v=\"1Tim.6.13\"></r>.†</s>","en":"<f><o>παρ-αγγέλλω</o></f> <et> <e t=\"derivation\">(&lt; <g>παρά</g>, <g>ἀγγὲλλω</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H8085\">שׁמע</h> pi., hi., etc.;]</e> </et> <s n=\"1.\"><b>to transmit a message</b> (Æsch., Eur.).</s> <s n=\"2.\"><b>to order</b>, <b>command</b> (Hdt., Xen., al.): c. inf., <r v=\"Acts.15.5\"></r>; c. acc. rei, <r v=\"1Cor.11.17\"></r>, <r v=\"2Thess.3.4\"></r>, <r v=\"1Tim.4.11\"></r> <r v=\"1Tim.5.7\"></r>; seq. <g>ἵνα</g> (M, <i>Pr.</i>, 207; Bl., § 69, 4), <r v=\"Mark.6.8\"></r>, <r v=\"2Thess.3.12\"></r>; c. dat. pers., <r v=\"Acts.17.30\"></r> R, txt., <r v=\"1Thess.4.11\"></r>; seq. <g>λέγων</g>, <r v=\"Matt.10.5\"></r>; c. inf. aor., <r v=\"Matt.15.35\"></r>, <r v=\"Mark.8.6\"></r>, <r v=\"Luke.8.29\"></r>, <r v=\"Acts.10.42\"></r> <r v=\"Acts.16.18\"></r> (aoristic pres.; v. M, <i>Pr.</i>, 119); id. c. neg., <g>μή</g>, <r v=\"Luke.5.14\"></r> <r v=\"Luke.8.56\"></r>, <r v=\"Acts.23.22\"></r>, <r v=\"1Cor.7.10\"></r>; c. inf. pres., <r v=\"Acts.16.23\"></r>, <r v=\"2Thess.3.6\"></r>; id. c. neg., <g>μή</g>, <r v=\"Luke.9.21\"></r>, <r v=\"Acts.1.4\"></r> <r v=\"Acts.4.18\"></r> <r v=\"Acts.5.28\"></r>, <r v=\"Acts.5.40\"></r>, <r v=\"1Tim.1.3\"></r> <r v=\"1Tim.6.17\"></r>; c. acc., <g>τοῦτο</g>, seq. <g>ὅτι</g> (B1., § 70, 3), <r v=\"2Thess.3.10\"></r>; c. acc. et inf., <r v=\"Acts.23.30\"></r>, <r v=\"2Thess.3.6\"></r>, <r v=\"1Tim.6.13\"></r> (Bl., § 72, 5).†</s> <sy><i>SYN.</i>: v.s. <g>ἐντέλλω</g>.</sy>"},"G3819":{"l":"πάλαι","o":7,"ar":"<f><o>πάλαι</o>،</f> ظرف زمان، <s><b>منذ زمن بعيد</b>، <b>قديمًا</b>، <b>في الزمن الماضي</b> (يدل على الزمن الماضي مطلقًا، كما يدل عليه <g>πρότερον</g> نسبيًا): <r v=\"Matt.11.21\"></r>، <r v=\"Luke.10.13\"></r>، <r v=\"Heb.1.1\"></r>، <r v=\"Jude.1.4\"></r>؛ بوصفه صفة، مع أداة التعريف، <r v=\"2Pet.1.9\"></r>؛ عن زمن مضى للتوّ، <r v=\"Mark.6.47\"></r>، <r v=\"Mark.15.44\"></r>؛ مع المضارع الدال على الاستمرار (<i>كل هذا الوقت</i>)، <r v=\"2Cor.12.19\"></r>.†</s>","en":"<f><o>πάλαι</o>,</f> adv. of time, <et> <e t=\"septuagint\">[in LXX: <r v=\"Isa.48.5\"></r>, <r v=\"Isa.48.7\"></r> (<h n=\"H227\">מֵאָז</h>), etc.;]</e> </et> <s><b>long ago</b>, <b>of old</b>, <b>in time past</b> (denoting past time absolutely, as <g>πρότερον</g> relatively): <r v=\"Matt.11.21\"></r>, <r v=\"Luke.10.13\"></r>, <r v=\"Heb.1.1\"></r>, <r v=\"Jude.1.4\"></r>; as adj., c. art., <r v=\"2Pet.1.9\"></r>; of time just past, <r v=\"Mark.6.47\"></r> (WH, mg.), <r v=\"Mark.15.44\"></r> (WH, mg., R, txt.); c. durat. praes. (RV, <i>all this time</i>), <r v=\"2Cor.12.19\"></r>.†</s>"},"G3890":{"l":"παραμύθιον","o":1,"ar":"<f>** <o>παραμύθιον</o>، <g>-ου, τό</g></f> <s n=\"1.\"><b>تحريض</b>، <b>إقناع</b>، <b>تشجيع</b>: <r v=\"Phil.2.1\"></r> (قارن <r v=\"Phil.2.1\"></r>).</s> <s n=\"2.\"><b>تسكين</b>، <b>تخفيف</b>، ومن ثمّ <b>تعزية</b> (<r v=\"Wis.3.18\"></r>).†</s>","en":"<f>** <o>παραμύθιον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>παραμυθέομαι</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Wis.3.18\"></r>*;]</e> </et> <s n=\"1.\"><b>an exhortation</b>, <b>persuasion</b>, <b>encouragement</b>: <r v=\"Phil.2.1\"></r> (cf. Plat., <i>Legg.</i>, vi, 773 E, al.; v. Lft. and <i>ICC</i>, <r v=\"Phil.2.1\"></r>).</s> <s n=\"2.\"><b>assuagement</b>, <b>abatement</b>, hence, <b>consolation</b> (<r v=\"Wis.3.18\"></r>, and freq. in cl.).†</s>"},"G3884":{"l":"παραλογίζομαι","o":2,"ar":"<f><o>παρα-λογίζομαι</o>،</f> <s n=\"1.\"><b>يخطئ في الحساب</b>.</s> <s n=\"2.\"><b>يستدلّ استدلالاً باطلاً</b>، ومن ثمّ <b>يخدع، يضلّل</b>: <r v=\"Col.2.4\"></r>، <r v=\"Jas.1.22\"></r>.†</s>","en":"<f><o>παρα-λογίζομαι</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7411\">רמה</h> pi.;]</e> </et> <s n=\"1.\"><b>to miscalculate</b>.</s> <s n=\"2.\"><b>to reason falsely</b>, hence, <b>to mislead</b>: <r v=\"Col.2.4\"></r>, <r v=\"Jas.1.22\"></r>.†</s>"},"G3844":{"l":"παρά","o":194,"ar":"<f><o>παρά</o>، حرف جر مع المضاف إليه والقابل والمنصوب،</f> <s>معناه الأصلي: <b>بجانب</b>. <s n=\"I.\">مع المضاف إليه للأشخاص: <b>من عند</b>، <b>من جانب</b>، <b>من</b>، دلالةً على المصدر أو الأصل، [في السبعينية ترجمةً لـ <h n=\"H681\">מֵאֵצֶל</h>، <h n=\"H3027\">מִיַד</h>، <h n=\"H6440\">מִלִּפְנֵי</h>؛] بعد أفعال الحركة، <r v=\"Mark.14.43\"></r>، <r v=\"Luke.8.49\"></r>، <r v=\"John.15.26\"></r>، وفي مواضع أخرى؛ بعد أفعال الطلب والأخذ والسماع وغيرها، <r v=\"Mark.8.11\"></r> <r v=\"Mark.12.2\"></r>، <r v=\"John.4.9\"></r>، <r v=\"John.4.52\"></r> <r v=\"John.10.18\"></r>، <r v=\"Phil.4.18\"></r>، <r v=\"2Tim.1.18\"></r>، <r v=\"Jas.1.7\"></r>، وفي مواضع أخرى؛ بعد الأفعال المبنية للمجهول، للدلالة على الفاعل (مثل <g>ὑπό</g>)، <r v=\"Matt.21.42\"></r>، <r v=\"Mark.12.11\"></r>، <r v=\"Luke.1.37\"></r>؛ مطلقًا، <g>οἱ παρ’ αὐτοῦ</g>: <b>أهله</b>، <b>أقرباؤه</b>، <r v=\"Mark.3.21\"></r>؛ <g>τὰ παρ’ αὐτῆς</g> (<g>αὐτῶν</g>، <g>ὑμῶν</g>): <b>ما عند المرء من مال</b>، <b>ثروة</b>، <r v=\"Mark.5.26\"></r>، <r v=\"Luke.10.7\"></r>، <r v=\"Phil.4.18\"></r>.</s> <s n=\"II.\">مع القابل للأشخاص (ما عدا <r v=\"John.19.25\"></r>، <g>π. τ. σταυρῷ</g>): <b>بجانب</b>، <b>بقرب</b>، <b>عند</b>، <b>مع</b>، [في السبعينية ترجمةً لـ <h n=\"H5869\">בְּעֵינֵי</h>، <h n=\"H3027\">בְּיַד</h>، <h n=\"H681\">אֵצֶל</h>؛] <r v=\"Luke.11.37\"></r> <r v=\"Luke.19.7\"></r>، <r v=\"John.1.40\"></r> <r v=\"John.4.40\"></r>، <r v=\"Acts.28.14\"></r>، وفي مواضع أخرى؛ <g>παρ’ ἑαυτῷ</g>: <b>في البيت</b>، <r v=\"1Cor.16.2\"></r>؛ مع القابل في الجمع: <b>بين</b>، <r v=\"Matt.22.25\"></r>، <r v=\"Col.4.16\"></r>، وفي مواضع أخرى؛ مجازيًا، <r v=\"Matt.19.26\"></r>، <r v=\"Mark.10.27\"></r>، <r v=\"Luke.1.30\"></r>، <r v=\"Rom.2.13\"></r>، <r v=\"Jas.1.27\"></r>، وفي مواضع أخرى.</s> <s n=\"III.\">مع المنصوب، للحركة بمحاذاة شيء أو نحوه، [في السبعينية ترجمةً لـ <h n=\"H5676,H5921,H3027,H681\">בְּעֵבֶר ,עַל יַד ,אֵצֶל</h>؛] <s n=\"1.\">عن المكان: <b>بجانب</b>، <b>بقرب</b>، <b>عند</b>، <b>على طول</b>: <r v=\"Acts.10.32\"></r>، <r v=\"Heb.11.12\"></r>؛ بعد أفعال الحركة، <r v=\"Matt.4.18\"></r>، <r v=\"Mark.4.4\"></r>، <r v=\"Luke.8.5\"></r>، <r v=\"Acts.4.35\"></r>، وفي مواضع أخرى؛ بعد أفعال السكون، <r v=\"Matt.13.1\"></r>، <r v=\"Mark.5.21\"></r>، <r v=\"Luke.8.35\"></r>، وفي مواضع أخرى.</s> <s n=\"2.\"><b>بجانب</b>، <b>أبعد من</b>، مجازيًا؛ <s n=\"(a)\"><b>بما يتجاوز</b>، <b>ضد</b>، <b>خلافًا لـ</b>: <r v=\"Acts.18.13\"></r>، <r v=\"Rom.1.26\"></r> <r v=\"Rom.4.18\"></r> <r v=\"Rom.11.24\"></r>، وفي مواضع أخرى؛ <b>إلا</b>، <r v=\"2Cor.11.24\"></r>؛</s> <s n=\"(b)\"><b>أكثر من</b>، <b>فوق</b>، <b>بالمقارنة مع</b>: <r v=\"Luke.3.13\"></r>، <r v=\"Rom.12.3\"></r> <r v=\"Rom.14.5\"></r>، <r v=\"Heb.1.4\"></r>، <r v=\"Heb.1.9\"></r> <r v=\"Heb.3.3\"></r>، وفي مواضع أخرى؛</s> <s n=\"(c)\"><b>بسبب</b>: <r v=\"1Cor.12.15\"></r>، <r v=\"1Cor.12.16\"></r>.</s> </s> </s> <s n=\"IV.\">في التركيب: <b>بجانب</b>، <b>إلى</b> (<g>παραλαμβάνω</g>، <g>παράγω</g>)، <b>حاضر، في المتناول</b> (<g>πάρειμι</g>)، <b>بعيدًا عن</b> (<g>παραρρέω</g>)، <b>خطأً</b> (<g>παρακούω</g>)، <b>مرورًا، تجاوزًا</b> (<g>παρέρχομαι</g>)، <b>بالمقارنة مع</b> (<g>παρομοιάζω</g>)، <b>فوق الحد</b> (<g>παροργίζω</g>).</s> </s>","en":"<f><o>παρά</o>, prep. c. gen., dat., acc.,</f> <s>with radical sense, <b>beside</b>. <s n=\"I.\">C. gen. pers., <b>from the side of</b>, <b>from beside</b>, <b>from</b>, indicating source or origin, [in LXX for <h n=\"H681\">מֵאֵצֶל</h>, <h n=\"H3027\">מִיַד</h>, <h n=\"H6440\">מִלִּפְנֵי</h>;] after verbs of motion, <r v=\"Mark.14.43\"></r>, <r v=\"Luke.8.49\"></r>, <r v=\"John.15.26\"></r>, al.; after verbs of seeking, receiving, hearing, etc., <r v=\"Mark.8.11\"></r> <r v=\"Mark.12.2\"></r>, <r v=\"John.4.9\"></r>, <r v=\"John.4.52\"></r> <r v=\"John.10.18\"></r>, <r v=\"Phil.4.18\"></r>, <r v=\"2Tim.1.18\"></r>, <r v=\"Jas.1.7\"></r>, al.; after passive verbs, of the agent (like <g>ὑπό</g>), <r v=\"Matt.21.42\"></r>, <r v=\"Mark.12.11\"></r>, <r v=\"Luke.1.37\"></r>; absol., <g>οἱ παρ’ αὐτοῦ</g>, <b>his family</b>, <b>his kinsfolk</b>, <r v=\"Mark.3.21\"></r> (cf. M, <i>Pr.</i>, 106 f.; Field, <i>Notes</i>, 25 f.; Swete, in l.); <g>τὰ παρ’ αὐτῆς</g> (<g>αὐτῶν</g>, <g>ὑμῶν</g>), <b>one's means</b>, <b>wealth</b>, <r v=\"Mark.5.26\"></r>, <r v=\"Luke.10.7\"></r>, <r v=\"Phil.4.18\"></r>.</s> <s n=\"II.\">C. dat. pers. (exc. <r v=\"John.19.25\"></r>, <g>π. τ. σταυρῷ</g>), <b>by the side of</b>, <b>beside</b>, <b>by</b>, <b>with</b>, [in LXX for <h n=\"H5869\">בְּעֵינֵי</h>, <h n=\"H3027\">בְּיַד</h>, <h n=\"H681\">אֵצֶל</h>;] <r v=\"Luke.11.37\"></r> <r v=\"Luke.19.7\"></r>, <r v=\"John.1.40\"></r> <r v=\"John.4.40\"></r>, <r v=\"Acts.28.14\"></r>, al.; <g>παρ’ ἑαυτῷ</g>, <b>at home</b>, <r v=\"1Cor.16.2\"></r>; c. dat. pl., <b>among</b>, <r v=\"Matt.22.25\"></r>, <r v=\"Col.4.16\"></r>, al.; metaph., <r v=\"Matt.19.26\"></r>, <r v=\"Mark.10.27\"></r>, <r v=\"Luke.1.30\"></r>, <r v=\"Rom.2.13\"></r>, <r v=\"Jas.1.27\"></r>, al.</s> <s n=\"III.\">C. acc., of motion by or towards, [in LXX for <h n=\"H5676,H5921,H3027,H681\">בְּעֵבֶר ,עַל יַד ,אֵצֶל</h>;] <s n=\"1.\">of place, <b>by the side of</b>, <b>beside</b>, <b>by</b>, <b>along</b>: <r v=\"Acts.10.32\"></r>, <r v=\"Heb.11.12\"></r>; after verbs of motion, <r v=\"Matt.4.18\"></r>, <r v=\"Mark.4.4\"></r>, <r v=\"Luke.8.5\"></r>, <r v=\"Acts.4.35\"></r>, al.; after verbs of rest, <r v=\"Matt.13.1\"></r>, <r v=\"Mark.5.21\"></r>, <r v=\"Luke.8.35\"></r>, al.</s> <s n=\"2.\"><b>beside</b>, <b>beyond</b>, metaph.; <s n=\"(a)\"><b>beyond</b>, <b>against</b>, <b>contrary to</b>: <r v=\"Acts.18.13\"></r>, <r v=\"Rom.1.26\"></r> <r v=\"Rom.4.18\"></r> <r v=\"Rom.11.24\"></r>, al.; <b>except</b>, <r v=\"2Cor.11.24\"></r>;</s> <s n=\"(b)\"><b>beyond</b>, <b>above</b>, <b>in comparison with</b>: <r v=\"Luke.3.13\"></r>, <r v=\"Rom.12.3\"></r> <r v=\"Rom.14.5\"></r>, <r v=\"Heb.1.4\"></r>, <r v=\"Heb.1.9\"></r> <r v=\"Heb.3.3\"></r>, al.;</s> <s n=\"(c)\"><b>on account of</b>: <r v=\"1Cor.12.15\"></r>, <r v=\"1Cor.12.16\"></r>.</s> </s> </s> <s n=\"IV.\">In composition: <b>beside</b>, <b>to</b> (<g>παραλαμβάνω</g>, <g>παράγω</g>), <b>at hand</b> (<g>πάρειμι</g>), <b>from</b> (<g>παραρρέω</g>), <b>amiss</b> (<g>παρακούω</g>), <b>past</b> (<g>παρέρχομαι</g>), <b>compared with</b> (<g>παρομοιάζω</g>), <b>above measure</b> (<g>παροργίζω</g>).</s> </s>"},"G3857":{"l":"παράδεισος","o":3,"ar":"<f><o>παράδεισος</o>، <g>-ου, ὁ</g></f> <s n=\"1.\"><b>حديقة</b>، <b>منتزه</b>، <b>جنّة</b> (السبعينية)، <b>بستان</b>.</s> <s n=\"2.\"><b>الفردوس</b>، مقرّ الموتى المطوّبين: <r v=\"Luke.23.43\"></r>، <r v=\"2Cor.12.4\"></r>، <r v=\"Rev.2.7\"></r>.†</s>","en":"<f><o>παράδεισος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(an Oriental word, first used by Xen. of the parks of Persian kings and nobles),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1588\">גַּן</h>, <r v=\"Gen.1.8\"></r> ff., al.; also for <h n=\"H5731\">עֵדֶן</h>, <r v=\"Isa.51.3\"></r>; <h n=\"H6508\">פַּרְדֵּס</h>, <r v=\"Neh.2.8\"></r>, <r v=\"Eccl.2.5\"></r>;]</e> </et> <s n=\"1.\"><b>a park</b>, <b>pleasure-ground</b>, <b>garden</b> (LXX), <b>an orchard</b> (in <g>π.</g>, v. MM, ii, xviii; Deiss., <i>BS</i>, 148).</s> <s n=\"2.\"><b>Paradise</b>, the abode of the blessed dead: <r v=\"Luke.23.43\"></r>, <r v=\"2Cor.12.4\"></r>, <r v=\"Rev.2.7\"></r>.†</s>"},"G3841":{"l":"παντοκράτωρ","o":10,"ar":"<f>† <o>παντοκράτωρ</o>، <g>-ορος, ὁ</g></f> <s><b>القادر على كل شيء</b>: <r v=\"2Cor.6.18\"></r>، <r v=\"Rev.1.8\"></r> <r v=\"Rev.4.8\"></r> <r v=\"Rev.11.17\"></r> <r v=\"Rev.15.3\"></r> <r v=\"Rev.16.7\"></r>، <r v=\"Rev.16.14\"></r> <r v=\"Rev.19.6\"></r>، <r v=\"Rev.9.15\"></r> <r v=\"Rev.21.22\"></r>.†</s>","en":"<f>† <o>παντοκράτωρ</o>, <g>-ορος, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>πᾶς</g>, <g>κρατέω</g>),</e> <e t=\"septuagint\">[in LXX: freq. in <r v=\"Job.5.8\"></r>, <r v=\"Job.5.17\"></r>, al. (<h n=\"H7706\">שַׁדַּי</h>), and for <h n=\"H6635\">צְבָאוֹת</h>, in the phrase <g>θεός</g> (<g>κυρίος</g>) <g>π.</g>, <r v=\"2Sam.5.10\"></r>, al., and freq. in Am, Za, Ma; also in <r v=\"Wis.7.25\"></r>, <r v=\"Sir.42.17\"></r> <r v=\"Sir.50.14\"></r>, <r v=\"Sir.50.17\"></r>, and freq. in Jth, II, III Mac;]</e> </et> <s><b>almighty</b>: <r v=\"2Cor.6.18\"></r>, <r v=\"Rev.1.8\"></r> <r v=\"Rev.4.8\"></r> <r v=\"Rev.11.17\"></r> <r v=\"Rev.15.3\"></r> <r v=\"Rev.16.7\"></r>, <r v=\"Rev.16.14\"></r> <r v=\"Rev.19.6\"></r>, <r v=\"Rev.9.15\"></r> <r v=\"Rev.21.22\"></r>.†</s>"},"G3850":{"l":"παραβολή","o":50,"ar":"<f><o>παραβολή</o>، <g>-ῆς, ἡ</g></f> <s n=\"1.\">عند الكتّاب المتأخرين: <b>وضع الشيء بجانب غيره</b>، <b>مجاورة</b>.</s> <s n=\"2.\">في اليونانية الكلاسيكية: <b>مقارنة</b>، <b>موازنة</b>.</s> <s n=\"3.\"><b>تشبيه</b>، <b>إيضاح</b>، <b>قياس</b>، <b>رمز</b>: <r v=\"Matt.24.32\"></r>، <r v=\"Mark.3.23\"></r>، <r v=\"Heb.9.9\"></r> <r v=\"Heb.11.19\"></r>؛ وتحديدًا عن الصور والقصص المأخوذة من الطبيعة والحياة البشرية، التي تميّز تعليم ربنا في الأناجيل الإزائية: <b>مَثَل</b>: <r v=\"Matt.13.3\"></r>، <r v=\"Matt.13.10\"></r>، <r v=\"Mark.4.2\"></r>، <r v=\"Mark.4.10\"></r>، <r v=\"Luke.8.4\"></r>، <r v=\"Luke.8.9-Luke.8.11\"></r>، وفي مواضع أخرى؛ مع المضاف إليه الدالّ على الموضوع، <r v=\"Matt.13.18\"></r>، <r v=\"Matt.13.36\"></r>.</s> <s n=\"4\">مثل العبرية <h n=\"H4911\">מָשָׁל</h> (<r v=\"1Sam.10.12\"></r>، <r v=\"Prov.1.6\"></r>، <r v=\"Sir.3.29\"></r>، وفي مواضع أخرى)، = <g>παροιμία</g>، <b>مَثَل سائر</b> أو قول حكمي: <r v=\"Luke.4.23\"></r> <r v=\"Luke.5.36\"></r> <r v=\"Luke.6.39\"></r>.</s>","en":"<f><o>παραβολή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>παραβάλλω</g>),</e> <e t=\"septuagint\">[in LXX (cf. McNeile, <i>Mt.</i>, 185): <r v=\"Num.23.7\"></r>, <r v=\"Deut.28.37\"></r>, <r v=\"Ps.44.14\"></r>, <r v=\"Prov.1.6\"></r>, <r v=\"Ezek.12.22\"></r>, al. (<h n=\"H4911\">מָשָׁל</h>), <r v=\"Sir.47.17\"></r> (<h n=\"H2420\">חִידָה</h>), al. mutt. in Si, <r v=\"Wis.5.3\"></r>;]</e> </et> <s n=\"1.\"><b>a placing beside</b>, <b>juxtaposition</b> (Polyb., al.).</s> <s n=\"2.\"><b>a comparing</b>, <b>comparison</b> (Plat., Arist., al.).</s> <s n=\"3.\"><b>a comparison</b>, <b>illustration</b>, <b>analogy</b>, <b>figure</b> (Arist., al.): <r v=\"Matt.24.32\"></r>, <r v=\"Mark.3.23\"></r>, <r v=\"Heb.9.9\"></r> <r v=\"Heb.11.19\"></r>; specif. of the pictures and narratives drawn from nature and human life which are characteristic of the synoptic teaching of our Lord, <b>a parable</b>: <r v=\"Matt.13.3\"></r>, <r v=\"Matt.13.10\"></r>, <r v=\"Mark.4.2\"></r>, <r v=\"Mark.4.10\"></r>, <r v=\"Luke.8.4\"></r>, <r v=\"Luke.8.9-Luke.8.11\"></r>, al.; c. gen. ref., <r v=\"Matt.13.18\"></r>, <r v=\"Matt.13.36\"></r>.</s> <s n=\"4\">Like Heb. <h n=\"H4911\">מָשָׁל</h> (<r v=\"1Sam.10.12\"></r>, <r v=\"Prov.1.6\"></r>, <r v=\"Sir.3.29\"></r>, al.), = <g>παροιμία</g>, <b>a proverb</b> or gnomic saying: <r v=\"Luke.4.23\"></r> <r v=\"Luke.5.36\"></r> <r v=\"Luke.6.39\"></r>.</s> <sy><i>SYN.</i>: <g>παροιμία</g> (v. Abbott, <i>Essays</i>, 82 ff.).</sy>"},"G3879":{"l":"παρακύπτω","o":5,"ar":"<f><o>παρα-κύπτω</o>،</f> <s n=\"1.\"><b>انحنى جانبًا</b>.</s> <s n=\"2.\"><b>انحنى لينظر</b>: <r v=\"Luke.24.12\"></r>، <r v=\"John.20.5\"></r>، <r v=\"John.20.11\"></r>. مجازيًا، <b>تطلّع إلى، تأمّل</b>: يليه <g>εἰς</g>، <r v=\"Jas.1.25\"></r>، <r v=\"1Pet.1.12\"></r>.†</s>","en":"<f><o>παρα-κύπτω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8259\">שׁקף</h> ni., hi.;]</e> </et> <s n=\"1.\"><b>to stoop sideways</b>.</s> <s n=\"2.\"><b>to stoop to look</b>: <r v=\"Luke.24.12\"></r> (R, txt.), <r v=\"John.20.5\"></r>, <r v=\"John.20.11\"></r>. Metaph. (v. Hort, <i>Ja.</i>, in l.), <b>to look into</b>: seq. <g>εἰς</g>, <r v=\"Jas.1.25\"></r>, <r v=\"1Pet.1.12\"></r>.†</s>"},"G3838":{"l":"παντελής","o":2,"ar":"<f>** <o>παντελής</o>، <g>-ές</g></f> <s><b>كامل من كل وجه</b>، <b>تام</b>، <b>كامل</b>؛ <g>εἰς τ. παντελές</g>، <b>تمامًا</b>، <b>إلى التمام</b>: <r v=\"Luke.13.11\"></r>، <r v=\"Heb.7.25\"></r> (وربما هنا بمعنى زمني: <i>إلى النهاية، على الدوام</i>).†</s>","en":"<f>** <o>παντελής</o>, <g>-ές</g></f> <et> <e t=\"derivation\">(&lt; <g>πᾶς</g>, <g>τέλος</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"3Macc.7.16\"></r> A*;]</e> </et> <s><b>all-complete</b>, <b>entire</b>, <b>perfect</b>; <g>εἰς τ. παντελές</g>, <b>completely</b>, <b>utterly</b>: <r v=\"Luke.13.11\"></r>, <r v=\"Heb.7.25\"></r> (where perhaps in temp. sense, <i>finally</i>; v. MM, xviii).†</s>"},"G3856":{"l":"παραδειγματίζω","o":1,"ar":"<f>† <o>παρα-δειγματίζω</o></f> <s><b>جعله عبرة ومثالاً</b>؛ وبالمعنى السيئ، <b>شهّر به، عرّضه للخزي علنًا</b>: <r v=\"Heb.6.6\"></r>.†</s>","en":"<f>† <o>παρα-δειγματίζω</o></f> <et> <e t=\"derivation\">(&lt; <g>δείκνυμι</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Num.25.4\"></r> (<h n=\"H3363\">יקע</h> hi.), <r v=\"Jer.13.22\"></r> (<h n=\"H2554\">חמס</h> ni.), <r v=\"Ezek.28.17\"></r> (<h n=\"H7207\">רַאֲוָה</h>), <r v=\"Ezra.4.17\"></r>, <r v=\"Dan.2.5\"></r>*;]</e> </et> <s><b>to set forth as an example</b>; in bad sense, <b>to put to open shame</b>: <r v=\"Heb.6.6\"></r> (Polyb., Plut., al.).†</s>"},"G3875":{"l":"παράκλητος","o":5,"ar":"<f>** <o>παρά-κλητος</o>، <g>-ον</g></f> <s><b>المدعوّ للمعونة</b> في قضية أمام القضاء؛ ومن ثمّ، وفي الغالب كاسم، <g>ὁ π.</g>، <b>محامٍ</b>، <b>مُدافع</b>، <b>شفيع</b> (وكذلك في الأدب الرباني، <h n=\"????\">פְּרַקְלִיטָא</h>)، أي «صديق المتهم الذي يُدعى للشهادة لحسن سيرته أو لاستمالة العطف نحوه». وفي العهد الجديد خاصةً، <g>ὁ π.</g>، <s n=\"(a)\">عن المسيح، <r v=\"1John.2.1\"></r>؛</s> <s n=\"(b)\">عن الروح القدس (الترجمة المعتمدة: <i>المعزّي</i>)، <r v=\"John.14.16\"></r>، <r v=\"John.14.26\"></r>، <r v=\"John.15.26\"></r>، <r v=\"John.16.7\"></r>.</s> </s>","en":"<f>** <o>παρά-κλητος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>παρακαλέω</g>),</e> <e t=\"septuagint\">[in Aq., Th.: <r v=\"Job.16.2\"></r>*;]</e> </et> <s><b>called to one's aid</b> in a judicial cause (Dion. Cass.); hence, most freq. as subst., <g>ὁ π.</g>, <b>an advocate</b>, <b>pleader</b>, <b>intercessor</b> (Dem., al.; so in Rabbinic lit., <h n=\"????\">פְּרַקְלִיטָא</h>), \"a friend of the accused person, called to speak to his character, or otherwise enlist sympathy in his favour\" (Field, <i>Notes</i>, 102). In NT, specif., <g>ὁ π.</g>, <s n=\"(a)\">of Christ, <r v=\"1John.2.1\"></r> (v. <i>ICC</i>, <i>Jo. Epp.</i>, 23 ff.);</s> <s n=\"(b)\">of the Holy Spirit (AV, <i>comforter</i>; but v. opp. c.), <r v=\"John.14.16\"></r>, <r v=\"John.14.26\"></r> <r v=\"John.15.26\"></r> <r v=\"John.16.7\"></r> (cf. also Abbott, <i>Essays</i>, 86, 97; Deiss., <i>LAE</i>, 339 f.; MM, xviii; Westc., <i>Jo.</i>, ii, 188 ff.).</s> </s>"},"G3822":{"l":"παλαιόω","o":4,"ar":"<f><o>παλαιόω</o>، <g>-ῶ</g></f> <s><b>عتّق</b> أو <b>جعله قديمًا</b>: <r v=\"Heb.8.13\"></r>؛ المبني للمجهول، <b>عتق، شاخ، صار قديمًا</b>: عن الأشياء التي يُبليها الزمن والاستعمال (قارن <r v=\"John.9.13\"></r>، <r v=\"Isa.50.9\"></r>، وفي مواضع أخرى، وانظر تحت مدخل <g>παλαιός</g>)، <r v=\"Luke.12.33\"></r>، <r v=\"Heb.1.11\"></r><i>(السبعينية)</i>؛ <g>τὸ παλαιούμενον</g>، <r v=\"Heb.8.13\"></r> (حيث قد يكون لهذا وللمبني للمعلوم المذكور أعلاه معنى <i>أبطل، نسخ</i>).†</s>","en":"<f><o>παλαιόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>παλαιός</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1086\">בּלה</h>, pi., in pass. for <h>בּ׳</h> qal.;]</e> </et> <s><b>to make</b> or <b>declare old</b>: <r v=\"Heb.8.13\"></r>; pass., <b>to become old</b>: of things worn out by time and use (cf. <r v=\"John.9.13\"></r>, <r v=\"Isa.50.9\"></r>, al., and v.s. <g>παλαιός</g>), <r v=\"Luke.12.33\"></r>, <r v=\"Heb.1.11\"></r><i>(LXX)</i>; <g>τὸ παλαιούμενον</g>, <r v=\"Heb.8.13\"></r> (where this and the act., v. supr., may have the sense of <i>abrogate</i>, v. LS, Zorell, s.v.).†</s> <sy><i>SYN.</i>: <g>γηράσκω</g>.</sy>"},"G3894":{"l":"παραπικρασμός","o":2,"ar":"<f>† <o>παρα-πικρασμός</o>، <g>-οῦ, ὁ</g></f> <s><b>إسخاط، تمرّد</b>: <g>ἐν τῷ π.</g> (في العبرية: <i>في مريبة</i>)، <r v=\"Heb.3.8\"></r>، <r v=\"Heb.3.15\"></r><i>(السبعينية)</i>.†</s>","en":"<f>† <o>παρα-πικρασμός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>παραπικραίνω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Ps.95.8\"></r> (<h n=\"H4808\">מְרִיבָה</h> elsewhere rendered <g>Λοιδόρησις</g>, <r v=\"Exod.17.7\"></r>; <g>ἀντιλογία</g>, <r v=\"Deut.33.8\"></r>, al.; <g>λοιδορία</g>, <r v=\"Num.20.24\"></r>)*;]</e> </et> <s><b>provocation</b>: <g>ἐν τῷ π.</g> (Heb. <i>at Meribah</i>), <r v=\"Heb.3.8\"></r>, <r v=\"Heb.3.15\"></r><i>(LXX)</i>.†</s>"},"G3895":{"l":"παραπίπτω","o":1,"ar":"<f><o>παρα-πίπτω</o>،</f> <s n=\"1.\">في اليونانية الكلاسيكية (وهو الأكثر شيوعًا): <b>صادف في الطريق</b>، <b>حلّ بـ</b>.</s> <s n=\"2.\"><b>سقط في</b> (مع القابل، <r v=\"2Macc.10.4\"></r>).</s> <s n=\"3.\"><b>سقط</b>، <b>ارتدّ</b> (<r v=\"Ezek.14.13\"></r> <r v=\"Ezek.15.8\"></r> <r v=\"Ezek.18.24\"></r> <r v=\"Ezek.20.27\"></r> <r v=\"Ezek.22.4\"></r>، <r v=\"Wis.6.9\"></r> <r v=\"Wis.12.2\"></r>): مطلقًا، <r v=\"Heb.6.6\"></r>.</s> <s n=\"4.\"><b>أخفق</b> (عن <g>λόγος</g>، <r v=\"Ezra.6.10\"></r>؛ قارن <r v=\"1Sam.3.19\"></r>).†</s>","en":"<f><o>παρα-πίπτω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ezek.14.13\"></r> <r v=\"Ezek.15.8\"></r> <r v=\"Ezek.18.24\"></r> <r v=\"Ezek.20.27\"></r> (<h n=\"H4603\">מעל</h>), <r v=\"Ezek.22.4\"></r> (<h n=\"H816\">אשׁם</h>), <r v=\"Ezra.6.10\"></r> (<h n=\"H5307\">נפל</h> hi.), <r v=\"Wis.6.9\"></r> <r v=\"Wis.12.2\"></r>, <r v=\"2Macc.10.4\"></r> A*;]</e> </et> <s n=\"1.\">most freq. (Hdt., Thuc., al.), <b>to fall in one's way</b>, <b>befall</b>.</s> <s n=\"2.\"><b>to fall into</b> or <b>in</b> (seq. <g>εἰς</g>, Polyb.; c. dat., <r v=\"2Macc.10.4\"></r>).</s> <s n=\"3.\"><b>to fall away</b> (<r v=\"Ezek.14.13\"></r> <r v=\"Ezek.15.8\"></r> <r v=\"Ezek.18.24\"></r> <r v=\"Ezek.20.27\"></r> <r v=\"Ezek.22.4\"></r>, <r v=\"Wis.6.9\"></r> <r v=\"Wis.12.2\"></r>; in Polyb., c. gen.): absol., <r v=\"Heb.6.6\"></r>.</s> <s n=\"4.\"><b>to fail</b> (<g>λόγος</g>, <r v=\"Ezra.6.10\"></r>; cf. <r v=\"1Sam.3.19\"></r>).†</s>"},"G3886":{"l":"παραλύω","o":5,"ar":"<f><o>παρα-λύω</o>،</f> <s n=\"1.\"><b>فكّ من الجانب</b>، <b>أطلق</b>.</s> <s n=\"2.\"><b>أضعف</b>، <b>أوهن</b>؛ المبني للمجهول: <b>صار واهنًا</b>، وخاصةً بضربة الفالج: <r v=\"Luke.5.18\"></r>، <r v=\"Luke.5.24\"></r>، <r v=\"Acts.8.7\"></r> <r v=\"Acts.9.33\"></r>، <r v=\"Heb.12.12\"></r><i>(السبعينية)</i>.†</s>","en":"<f><o>παρα-λύω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Jer.6.24\"></r>, <r v=\"Jer.27.43\"></r>, <r v=\"Ezek.21.7\"></r> (<r v=\"Ezek.21.12\"></r>) (<h n=\"H7503\">רפה</h>), etc.;]</e> </et> <s n=\"1.\"><b>to loose from the side</b>, <b>set free</b>.</s> <s n=\"2.\"><b>to weaken</b>, <b>enfeeble</b>; pass., <b>to be enfeebled</b>, esp. by a paralytic stroke: <r v=\"Luke.5.18\"></r>, <r v=\"Luke.5.24\"></r>, <r v=\"Acts.8.7\"></r> <r v=\"Acts.9.33\"></r>, <r v=\"Heb.12.12\"></r><i>(LXX)</i>.†</s>"},"G3817":{"l":"παίω","o":20,"ar":"<f><o>παίω</o>،</f> <s><b>ضرب</b>، <b>لطم</b>: باليد أو بقبضة اليد، <r v=\"Matt.26.68\"></r>، <r v=\"Luke.22.64\"></r>؛ بالسيف، <r v=\"Mark.14.47\"></r>، <r v=\"John.18.10\"></r>؛ وعن الزواحف: <b>لدغ</b>: <r v=\"Rev.9.5\"></r>.†</s>","en":"<f><o>παίω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5221\">נכה</h> hi.;]</e> </et> <s><b>to strike</b>, <b>smite</b>: with the hand or fist, <r v=\"Matt.26.68\"></r>, <r v=\"Luke.22.64\"></r>; with a sword, <r v=\"Mark.14.47\"></r>, <r v=\"John.18.10\"></r>; of a reptile, <b>to sting</b>: <r v=\"Rev.9.5\"></r>.†</s>"},"G3883":{"l":"παραλλαγή","o":1,"ar":"<f><o>παρ-αλλαγή</o>، <g>-ῆς, ἡ</g></f> <s><b>تغيير</b>: <r v=\"Jas.1.17\"></r>.†</s>","en":"<f><o>παρ-αλλαγή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>παραλλάσσω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"2Kgs.9.20\"></r> (<h n=\"H7697\">שִׁגָּעוֹן</h>)*;]</e> </et> <s>in various senses (LS, s.v.), <b>change</b>: <r v=\"Jas.1.17\"></r>.†</s>"},"G3893":{"l":"παραπικραίνω","o":1,"ar":"<f>† <o>παρα-πικραίνω</o>،</f> <s><b>أمرّ، أسخط، أغاظ</b>: مطلقًا (ولكن يُفهم <g>τ. θεόν</g>، قارن <r v=\"Ps.106.7\"></r>، <r v=\"Ezek.2.5-Ezek.2.8\"></r>، وفي مواضع أخرى؛ ومع إضافة <g>τὸν θ.</g>، <r v=\"Ps.5.4\"></r>، <r v=\"Ezek.20.21\"></r>، وفي مواضع أخرى)، <r v=\"Heb.3.16\"></r> (قارن <g>παραπικρασμός</g>).†</s>","en":"<f>† <o>παρα-πικραίνω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4784\">מרה</h> qal., hi., <h n=\"H4805\">מְרִי</h>, most freq. in Pss and Ez;]</e> </et> <s><b>to embitter</b>, <b>provoke</b>: absol. (yet sc. <g>τ. θεόν</g>, cf. <r v=\"Ps.106.7\"></r>, <r v=\"Ezek.2.5-Ezek.2.8\"></r>, al., and with <g>τὸν θ.</g> added, <r v=\"Ps.5.4\"></r>, <r v=\"Ezek.20.21\"></r>, al.), <r v=\"Heb.3.16\"></r> (cf. <g>παραπικρασμός</g>).†</s>"},"G3892":{"l":"παρανομία","o":1,"ar":"<f><o>παρανομία</o>، <g>-ας, ἡ</g>،</f> <s><b>مخالفة الناموس</b>، <b>تعدٍّ</b>: <r v=\"2Pet.2.16\"></r>.†</s>","en":"<f><o>παρανομία</o>, <g>-ας, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ps.37.7\"></r> (<h n=\"H4209\">מְזִמָּה</h>), etc.;]</e> </et> <s><b>law-breaking</b>, <b>transgression</b>: <r v=\"2Pet.2.16\"></r>.†</s>"},"G3831":{"l":"πανήγυρις","o":1,"ar":"<f><o>πανήγυρις</o>، <g>-εως, ἡ</g></f> <s>أصلاً <b>محفل احتفالي قومي</b> إكرامًا لإله؛ ومن ثمّ عمومًا أي <b>محفل احتفالي، جماعة محتفلة</b>: <r v=\"Heb.12.23\"></r>.†</s>","en":"<f><o>πανήγυρις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>πᾶς</g> + <g>ἄγυρας</g> = <g>ἀγορά</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Hos.2.11\"></r> (<r v=\"Hos.2.13\"></r>) 9:5, <r v=\"Ezek.46.11\"></r> (<h n=\"H4150\">מוֹעֵד</h>), <r v=\"Amos.5.21\"></r> (<h n=\"H6116\">עֲצָרָה</h>)*;]</e> </et> <s>prop., <b>a national festal assembly</b> in honour of a god; hence, generally, any <b>festal assembly</b>: <r v=\"Heb.12.23\"></r> (for exx. in <g>π.</g>, v. MM, xviii).†</s> <sy><i>SYN.</i>: <g>ἐκκλησία</g> (q.v.), <g>συναγωγή</g>.</sy>"},"G3840":{"l":"πάντοθεν","o":3,"ar":"<f><o>πάντοθεν</o>،</f> ظرف <s><b>من كل ناحية</b>: <r v=\"Mark.1.45\"></r>، <r v=\"Luke.19.43\"></r>، <r v=\"Heb.9.4\"></r>.†</s>","en":"<f><o>πάντοθεν</o>,</f> adv. <et> <e t=\"derivation\">(&lt; <g>πᾶς</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Jer.48.31\"></r> (<h n=\"H3605\">כֻּלֹּה</h>), al.;]</e> </et> <s><b>from all sides</b>: <r v=\"Mark.1.45\"></r>, <r v=\"Luke.19.43\"></r>, <r v=\"Heb.9.4\"></r>.†</s>"},"G3849":{"l":"παραβιάζομαι","o":2,"ar":"<f>† <o>παρα-βιάζομαι</o>،</f> <s n=\"1.\">أصلاً، <b>أكره على خلاف الطبيعة</b> أو <b>الناموس</b>.</s> <s n=\"2.\">عند الكتّاب المتأخرين: <b>ألزم بالقوة</b>.</s> <s n=\"3.\"><b>ألحَّ عليه بالرجاء</b> (<r v=\"Gen.19.9\"></r>، <r v=\"1Sam.28.23\"></r>): <r v=\"Luke.24.29\"></r>، <r v=\"Acts.16.15\"></r>.†</s>","en":"<f>† <o>παρα-βιάζομαι</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Gen.19.9\"></r>, <r v=\"2Kgs.2.17\"></r> (<h>בְּ׳</h> <h n=\"H6484\">פָּצַר</h>), <r v=\"Deut.1.43\"></r> (<h n=\"H2102\">זוּד</h> hi.), <r v=\"1Sam.28.23\"></r> (<h>בְּ׳</h> <h n=\"H6555\">פָּרַץ</h>) v.1.<i>4</i>*;]</e> </et> <s n=\"1.\">prop., <b>to force against nature</b> or <b>law</b>.</s> <s n=\"2.\"><b>to compel by force</b> (Polyb.).</s> <s n=\"3.\"><b>to constrain by entreaty</b> (<r v=\"Gen.19.9\"></r>, <r v=\"1Sam.28.23\"></r>): <r v=\"Luke.24.29\"></r>, <r v=\"Acts.16.15\"></r>.†</s>"},"G3802":{"l":"παγιδεύω","o":1,"ar":"<f>† <o>παγιδεύω</o></f> <s><b>اصطاد بفخ</b>: مجازيًا، مع المنصوب، <g>ἐν λόγῳ</g>، <r v=\"Matt.22.15\"></r> (ولا يرد في موضع آخر).†</s>","en":"<f>† <o>παγιδεύω</o></f> <et> <e t=\"derivation\">(&lt; <g>παγίς</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"1Sam.28.9\"></r> (<h n=\"H5367\">נקשׁ</h> hith.), <r v=\"Eccl.9.12\"></r> (<h n=\"H3369\">יקשׁ</h> pu.)*;]</e> </et> <s><b>to ensnare</b>: metaph., c. acc., <g>ἐν λόγῳ</g>, <r v=\"Matt.22.15\"></r> (not elsewhere).†</s>"},"G3846":{"l":"παραβάλλω","o":1,"ar":"<f><o>παρα-βάλλω</o>،</f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>ألقى إلى</b> أو <b>بجانب</b>، كما يُلقى العلف للخيل.</s> <s n=\"2.\"><b>وضع بجانب</b>، <b>قارن</b>: <r v=\"Mark.4.30\"></r>، في النص المستلَم.</s> <s n=\"3.\">انعكاسيًا: <b>توجّه</b>، <b>اقترب</b>؛ وعن البحّارة: <b>عبر</b>: <g>εἰς Σάμον</g>، <r v=\"Acts.20.15\"></r>.</s> <s n=\"4.\">وفي الصيغة الوسطى = <g>παρα-βολεύομαι</g>، انظره.†</s>","en":"<f><o>παρα-βάλλω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Prov.2.2\"></r> <r v=\"Prov.4.20\"></r> <r v=\"Prov.5.1\"></r>, <r v=\"Prov.5.13\"></r> <r v=\"Prov.22.17\"></r> (<h n=\"H5186\">נטה</h> hi.), <r v=\"Ruth.2.16\"></r> (<h n=\"H7997\">שׁלל</h>), <r v=\"2Macc.14.38\"></r> (elsewhere as v.l.<i>4</i>)*;]</e> </et> <s n=\"1.\"><b>to throw to</b> or <b>beside</b>, as fodder to horses (Hom., al.).</s> <s n=\"2.\"><b>to lay beside</b>, <b>compare</b> (Hdt., Plat., al.): <r v=\"Mark.4.30\"></r>, Rec.</s> <s n=\"3.\">Reflexive, <b>to betake oneself</b>, <b>come near</b>; of seamen, <b>to cross over</b>: <g>εἰς Σάμον</g>, <r v=\"Acts.20.15\"></r>.</s> <s n=\"4.\">In mid. = <g>παρα-βολεύομαι</g>, q.v.†</s>"},"G3828":{"l":"Παμφυλία","o":5,"ar":"<f><o>Παμφυλία</o>، <g>-ας, ἡ</g>،</f> <s><b>بمفيلية</b>، إقليم في آسيا الصغرى: <r v=\"Acts.2.10\"></r> <r v=\"Acts.13.13\"></r> <r v=\"Acts.14.24\"></r> <r v=\"Acts.15.38\"></r> <r v=\"Acts.27.5\"></r>.†</s>","en":"<f><o>Παμφυλία</o>, <g>-ας, ἡ</g>,</f> <s><b>Pamphylia</b>, a province of Asia Minor: <r v=\"Acts.2.10\"></r> <r v=\"Acts.13.13\"></r> <r v=\"Acts.14.24\"></r> <r v=\"Acts.15.38\"></r> <r v=\"Acts.27.5\"></r>.†</s>"},"G3826":{"l":"πανπληθεί","o":1,"ar":"<f>*† <o>πανπληθεί</o></f> ظرف <s>= الكلاسيكية <g>παμπληθές</g>، <b>بجملة الجمهور</b>، <b>جميعًا معًا</b>: <r v=\"Luke.23.18\"></r>.†</s>","en":"<f>*† <o>πανπληθεί</o> (Rec. <g>παμπλ-</g>, v. WH, <i>App.</i>, 150),</f> adv. <et> <e t=\"derivation\">(&lt; <g>πᾶς</g>, <g>πλῆθος</g>),</e> </et> <s>= cl. <g>παμπληθές</g>, <b>with the whole multitude</b>, <b>all together</b>: <r v=\"Luke.23.18\"></r>.†</s>"},"G3891":{"l":"παρανομέω","o":1,"ar":"<f><o>παρα-νομέω</o>، <g>ῶ</g>،</f> <s>أن يكون المرء <g>παράνομος</g>، <b>خالف الناموس</b>: <r v=\"Acts.23.3\"></r>.†</s>","en":"<f><o>παρα-νομέω</o>, <g>ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H1984\">חלל</h>, etc., chiefly in Pss and II Mac;]</e> </et> <s>to be a <g>παράνομος</g>, <b>to transgress the law</b>: <r v=\"Acts.23.3\"></r>.†</s>"},"G3864":{"l":"παραθαλάσσιος","o":1,"ar":"<f><o>παρα-θαλάσσιος</o>، <g>-α, -ον</g></f> <s><b>عند البحر، ساحلي</b>: <r v=\"Matt.4.13\"></r>.†</s>","en":"<f><o>παρα-θαλάσσιος</o>, <g>-α, -ον</g></f> <et> <e t=\"derivation\">(&lt; <g>παρά</g>, <g>θάλασσα</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Jer.47.7\"></r> (<h n=\"H3220\">היָּם</h> <h n=\"H2348\">חוֹף</h>), etc.;]</e> </et> <s><b>by the sea</b>: <r v=\"Matt.4.13\"></r>.†</s>"},"G3808":{"l":"παιδάριον","o":1,"ar":"<f><o>παιδάριον</o>، <g>-ου, τό</g>، تصغير <g>παῖς</g>،</f> <s><b>صبي صغير</b>، <b>غلام</b> (في اليونانية المتأخرة والدارجة يبدو أن الكلمة استُعملت بمعنى أوسع، بل فقدت معنى التصغير كليًا؛ قارن <r v=\"Tob.6.2\"></r>، <r v=\"Tob.6.3\"></r>): <r v=\"John.6.9\"></r>.†</s>","en":"<f><o>παιδάριον</o>, <g>-ου, τό</g>, dimin. of <g>παῖς</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5288\">נַעַר</h>;]</e> </et> <s><b>a little boy</b>, <b>a lad</b> (in late and colloq. Gk. the word seems to be used with greater latitude and even to lose its dimin. force entirely; cf. <r v=\"Tob.6.2\"></r>, <r v=\"Tob.6.3\"></r>, and v. MM, xviii): <r v=\"John.6.9\"></r>.†</s> <sy><i>SYN.</i>: v.s. <g>παῖς</g>.</sy>"},"G3867":{"l":"παραινέω","o":2,"ar":"<f>** <o>παρ-αινέω</o>، <g>-ῶ</g>،</f> <s><b>يحثّ</b>، <b>ينصح</b>: مع المنصوب للشخص والمصدر، <r v=\"Acts.27.22\"></r>؛ مطلقًا، يليه <g>λέγων</g>، <r v=\"Acts.27.9\"></r>.†</s>","en":"<f>** <o>παρ-αινέω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"2Macc.7.25\"></r>, <r v=\"2Macc.7.26\"></r>, <r v=\"3Macc.5.17\"></r> <r v=\"3Macc.7.12\"></r>*;]</e> </et> <s><b>to</b> <b>exhort</b>, <b>advise</b>: c. acc. pers. et inf. (v. Bl., § 72, 5; M, <i>Pr.</i>, 205), <r v=\"Acts.27.22\"></r>; absol., seq. <g>λέγων</g>, <r v=\"Acts.27.9\"></r>.†</s>"},"G3816":{"l":"παῖς","o":24,"ar":"<f><o>παῖς</o>، حالة الجر: <g>παιδός, ὁ, ἡ</g>،</f> <s n=\"1.\"><b>طفل، صبي</b>، <b>فتى</b>، <b>فتاة</b>: <g>ὁ π.</g>، <r v=\"Matt.17.18\"></r>، <r v=\"Luke.2.43\"></r>، <r v=\"Luke.9.42\"></r>، <r v=\"Acts.20.12\"></r>؛ <g>ἡ π.</g>، <r v=\"Luke.8.51\"></r>، <r v=\"Luke.8.54\"></r>؛ جمع، <r v=\"Matt.2.16\"></r>، <r v=\"Matt.21.15\"></r>؛ عن البنوّة، مع المضاف إليه، <r v=\"John.4.51\"></r>.</s> <s n=\"2.\">مثل العبرية <h n=\"H5650\">עֶבֶד</h>، واللاتينية <l>puer</l>، والفرنسية <l>garçon</l>: <b>غلام</b>، <b>خادم</b>، <b>عبد</b>، <b>تابع</b>: <r v=\"Matt.8.6\"></r>، <r v=\"Matt.8.8\"></r>، <r v=\"Matt.8.13\"></r>، <r v=\"Luke.7.7\"></r>، <r v=\"Luke.12.45\"></r>، <r v=\"Luke.15.26\"></r>؛ وعند الكتّاب المتأخرين (والسبعينية: <r v=\"Gen.41.37\"></r>، وفي مواضع أخرى)، عن تابع الملك أو وزيره: <r v=\"Matt.14.2\"></r>؛ وهكذا (= العبرية <h n=\"H5650\">עֶבֶד</h> <h n=\"H3068\">יְהֹוָה</h>) <g>π. τ. θεοῦ</g> (<r v=\"Ps.69.18\"></r>، <r v=\"Isa.41.8\"></r>، <r v=\"Wis.2.13\"></r>، وفي مواضع أخرى)، عن إسرائيل، <r v=\"Luke.1.54\"></r>؛ عن داود، <r v=\"Luke.1.69\"></r>، <r v=\"Acts.4.25\"></r>؛ عن يسوع، <r v=\"Matt.12.18\"></r> <i>(السبعينية)</i>، <r v=\"Acts.3.13\"></r>، <r v=\"Acts.3.26\"></r>، <r v=\"Acts.4.27\"></r>، <r v=\"Acts.4.30\"></r>.†</s>","en":"<f><o>παῖς</o>, gen., <g>παιδός, ὁ, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5650\">עֶבֶד</h>, also for <h n=\"H5288\">נַעַר</h>, <h n=\"H5291\">נַעֲרָה</h>, etc.;]</e> </et> <s n=\"1.\"><b>a child, boy</b>, <b>youth</b>, <b>maiden</b>: <g>ὁ π.</g>, <r v=\"Matt.17.18\"></r>, <r v=\"Luke.2.43\"></r> <r v=\"Luke.9.42\"></r>, <r v=\"Acts.20.12\"></r>; <g>ἡ π.</g> <r v=\"Luke.8.51\"></r>, <r v=\"Luke.8.54\"></r> (on the artic. nom, of address, v. M, <i>Pr.</i>, 70 f., 235; Bl., § 33, 4); pl., <r v=\"Matt.2.16\"></r> <r v=\"Matt.21.15\"></r>; of parentage, c. gen., <r v=\"John.4.51\"></r>.</s> <s n=\"2.\">Like Heb. <h n=\"H5650\">עֶבֶד</h>, Lat. <l>puer</l>, Fr. <l>garçon</l>, Eng. <b>boy</b> (Æsch., Aristoph., Xen., al.), <b>servant</b>, <b>slave</b>, <b>attendant</b>: <r v=\"Matt.8.6\"></r>, <r v=\"Matt.8.8\"></r>, <r v=\"Matt.8.13\"></r>, <r v=\"Luke.7.7\"></r> <r v=\"Luke.12.45\"></r> <r v=\"Luke.15.26\"></r>; in late writers (Diod., LXX: <r v=\"Gen.41.37\"></r>, al.), of a king's attendant or minister: <r v=\"Matt.14.2\"></r>; so (= Heb. <h n=\"H5650\">עֶבֶד</h> <h n=\"H3068\">יְהֹוָה</h>) <g>π. τ. θεοῦ</g> (<r v=\"Ps.69.18\"></r>, <r v=\"Isa.41.8\"></r>, <r v=\"Wis.2.13\"></r>, al.), of Israel, <r v=\"Luke.1.54\"></r>; of David, <r v=\"Luke.1.69\"></r>, <r v=\"Acts.4.25\"></r>; of Jesus (but v. Dalman, <i>Words</i>, 277 f.), <r v=\"Matt.12.18\"></r><i>(LXX)</i>, <r v=\"Acts.3.13\"></r>, <r v=\"Acts.3.26\"></r> <r v=\"Acts.4.27\"></r>, <r v=\"Acts.4.30\"></r>.†</s> <sy><i>SYN.</i>: 1. <g>τέκνον</g>, <i>child</i>, with emphasis on parentage and the consequent community of nature; <g>υἱός</g>, <i>son</i>, with emphasis on the privileged position of heirship; <g>π.</g> refers both to age and parentage, but with emphasis on the former. Cf. also <g>παιδάριον</g>, <g>παιδίον</g>, <g>παιδίσκη</g>, and v. Westc. on <r v=\"1John.3.1\"></r>. 2. v.s. <g>θεράπων</g>, and cf. Thackeray, <i>Gr.</i>, 7 f.</sy>"},"G3882":{"l":"παράλιος","o":1,"ar":"<f><o>παρ-άλιος</o>، <g>-ον</g></f> <s><b>ساحلي (بجانب البحر)</b>؛ <g>ἡ π.</g> (أي <g>χώρα</g>، وفي السبعينية <g>ἡ παραλία</g>، <r v=\"Deut.1.7\"></r>، <r v=\"Josh.9.1\"></r>، <r v=\"Jdt.1.7\"></r>، وفي مواضع أخرى)، <b>الساحل</b>: <r v=\"Luke.6.17\"></r>.†</s>","en":"<f><o>παρ-άλιος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(in cl., chiefly <g>-α, -ον</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H3220\">יָם</h>, <h n=\"H3220\">הַיָּם</h>, <h n=\"H2348\">חוֹף</h>, etc., c. prep.;]</e> </et> <s><b>by the sea</b>; <g>ἡ π.</g> (sc. <g>χώρα</g>, in LXX <g>ἡ παραλία</g>, <r v=\"Deut.1.7\"></r>, <r v=\"Josh.9.1\"></r>, <r v=\"Jdt.1.7\"></r>, al.), <b>the sea coast</b>: <r v=\"Luke.6.17\"></r>.†</s>"},"G3829":{"l":"πανδοχεῖον","o":1,"ar":"<f>* <o>παν-δοχεῖον</o>، <g>-ου, τό</g></f> <s><b>فندق، خان</b> (<l>khân</l>، <l>caravanserai</l>): <r v=\"Luke.10.34\"></r>.†</s>","en":"<f>* <o>παν-δοχεῖον</o> (<g>-δοκίον</g>, T), <g>-ου, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>πανδοχεύς</g>),</e> <e t=\"derivation\">late form of Att. <g>πανδοκεῖον</g>,</e> </et> <s><b>an inn</b> (<l>khân</l>, <l>caravanserai</l>): <r v=\"Luke.10.34\"></r>.†</s>"},"G3899":{"l":"παραπορεύομαι","o":5,"ar":"<f><o>παρα-πορεύομαι</o>،</f> <s n=\"1.\"><b>سار بجانب</b>، <b>رافق</b>.</s> <s n=\"2.\"><b>اجتاز</b>، <b>مرّ</b>: <r v=\"Matt.27.39\"></r>، <r v=\"Mark.11.20\"></r> <r v=\"Mark.15.29\"></r>؛ يليه <g>διά</g>، مع المضاف إليه، <r v=\"Mark.2.23\"></r> <r v=\"Mark.9.30\"></r>.†</s>","en":"<f><o>παρα-πορεύομαι</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5674\">עבר</h>;]</e> </et> <s n=\"1.\"><b>to go beside</b>, <b>accompany</b>.</s> <s n=\"2.\"><b>to go past</b>, <b>pass by</b>: <r v=\"Matt.27.39\"></r>, <r v=\"Mark.11.20\"></r> <r v=\"Mark.15.29\"></r>; seq. <g>διά</g>, c. gen., <r v=\"Mark.2.23\"></r> <r v=\"Mark.9.30\"></r> (WH, mg.).†</s>"},"G3869":{"l":"παρακαθίζω","o":1,"ar":"<f><o>παρα-καθίζω</o>،</f> <s><b>أجلس بجانب</b>؛ المبني للمعلوم بمعنى الصيغة الوسطى، <b>جلس بجانب</b>: <r v=\"Luke.10.39\"></r>، في النص المستلَم (بدل <g>-έζομαι</g>، انظره).†</s>","en":"<f><o>παρα-καθίζω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Job.2.13\"></r> (<h n=\"H3427\">ישׁב</h>)*;]</e> </et> <s><b>to set beside</b>; act. for mid., <b>to sit down beside</b>: <r v=\"Luke.10.39\"></r>, Rec. (for <g>-έζομαι</g>, q.v.).†</s>"},"G3830":{"l":"πανδοχεύς","o":1,"ar":"<f>* <o>παν-δοχεύς</o>، <g>-έως, ὁ</g></f> <s><b>صاحب الفندق</b>، <b>مُضيف</b>: <r v=\"Luke.10.35\"></r>.†</s>","en":"<f>* <o>παν-δοχεύς</o>, <g>-έως, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>πᾶς</g>, <g>δέχομαι</g>),</e> <e t=\"derivation\">late form of the Att. <g>πανδοκεύς</g> (T, in l.),</e> </et> <s><b>an innkeeper</b>, <b>host</b>: <r v=\"Luke.10.35\"></r>.†</s>"},"G3845":{"l":"παραβαίνω","o":3,"ar":"<f><o>παρα-βαίνω</o>،</f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>سار بجانب</b>، <b>وقف بجانب</b>.</s> <s n=\"2.\">ثم <b>اجتاز</b> أو <b>تخطّى</b>، ومجازيًا في الغالب <b>تجاوز</b>، <b>نقض</b>، <b>تعدّى</b> (<r v=\"Josh.7.11\"></r>، <r v=\"Ezek.16.59\"></r>، <r v=\"Sir.40.14\"></r>، وفي مواضع أخرى): <g>τ. παράδοσιν</g>، <r v=\"Matt.15.2\"></r>؛ <g>τ. ἐντολήν</g>، <r v=\"Matt.15.3\"></r>؛ يليه <g>ἀπό</g> (كما في <h n=\"H5493\">סוּר</h> <h n=\"H4480\">מִן</h>، <r v=\"Deut.17.20\"></r>، وفي مواضع أخرى)، <b>حاد</b>، <b>سقط</b>: <r v=\"Acts.1.25\"></r>.†</s>","en":"<f><o>παρα-βαίνω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5493\">סוּר</h>, <h n=\"H5674\">עבר</h>, <h n=\"H6565\">פּרר</h> hi., <h n=\"H7847\">שׂטה</h>, etc.;]</e> </et> <s n=\"1.\">in Hom. (twice), <b>to go by the side of</b>, <b>stand beside</b>.</s> <s n=\"2.\">In Æsch., Herod., Thuc., al., <b>to go past</b> or <b>pass over</b>, chiefly metaph., <b>to overstep</b>, <b>violate</b>, <b>transgress</b> (<r v=\"Josh.7.11\"></r>, <r v=\"Ezek.16.59\"></r>, <r v=\"Sir.40.14\"></r>, al.): <g>τ. παράδοσιν</g>, <r v=\"Matt.15.2\"></r>; <g>τ. ἐντολήν</g>, <r v=\"Matt.15.3\"></r>; seq. <g>ἀπό</g> (as <h n=\"H5493\">סוּר</h> <h n=\"H4480\">מִן</h>, <r v=\"Deut.17.20\"></r>, al.), <b>to turn aside</b>, <b>fall away</b> (cf. <g>π. τῆς ἀληθείας</g>, Arist., <i>Cael.</i>, i, 5, 2): <r v=\"Acts.1.25\"></r>.†</s>"},"G3885":{"l":"παραλυτικός","o":10,"ar":"<f>*† <o>παρα-λυτικός</o>، <g>-ή, -όν</g></f> <s><b>مفلوج</b>: <r v=\"Matt.4.24\"></r> <r v=\"Matt.8.6\"></r> <r v=\"Matt.9.2\"></r>، <r v=\"Matt.9.6\"></r>، <r v=\"Mark.2.3-Mark.2.5\"></r>، <r v=\"Mark.2.9\"></r>، <r v=\"Mark.2.10\"></r>، <r v=\"Luke.5.24\"></r>.†</s>","en":"<f>*† <o>παρα-λυτικός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>παραλύω</g>),</e> </et> <s><b>paralytic</b>: <r v=\"Matt.4.24\"></r> <r v=\"Matt.8.6\"></r> <r v=\"Matt.9.2\"></r>, <r v=\"Matt.9.6\"></r>, <r v=\"Mark.2.3-Mark.2.5\"></r>, <r v=\"Mark.2.9\"></r>, <r v=\"Mark.2.10\"></r>, <r v=\"Luke.5.24\"></r> (Rec., WH, mg.).†</s>"},"G3861":{"l":"παράδοξος","o":1,"ar":"<f>** <o>παράδοξος</o>، <g>-ον</g></f> <s><b>مخالف للمألوف</b>، <b>لا يُصدَّق</b>، <b>عجيب</b>: جمعًا، <r v=\"Luke.5.26\"></r>.†</s>","en":"<f>** <o>παράδοξος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>παρά</g>, <g>δόξα</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Jdt.13.13\"></r>, <r v=\"Wis.5.2\"></r> <r v=\"Wis.16.17\"></r> <r v=\"Wis.19.5\"></r>, <r v=\"Sir.43.25\"></r>; II-IV Mac<i>3</i>*;]</e> </et> <s><b>contrary to received opinion</b>, <b>incredible</b>, <b>marvellous</b>: pl., <r v=\"Luke.5.26\"></r>.†</s> <sy><i>SYN.</i>: v.s. <g>δύναμις</g>.</sy>"},"G3896":{"l":"παραπλέω","o":1,"ar":"<f>* <o>παρα-πλέω</o>،</f> <s><b>أبحر بمحاذاة</b> أو <b>متجاوزًا</b>: مع المنصوب، <r v=\"Acts.20.16\"></r>.†</s>","en":"<f>* <o>παρα-πλέω</o>,</f> <s><b>to sail by</b> or <b>past</b>: c. acc., <r v=\"Acts.20.16\"></r>.†</s>"},"G3878":{"l":"παρακούω","o":3,"ar":"<f><o>παρ-ακούω</o>،</f> <s n=\"1.\"><b>سمع عَرَضًا، استرق السمع</b>.</s> <s n=\"2.\"><b>أساء السمع</b> أو <b>سمع سماعًا ناقصًا</b>.</s> <s n=\"3.\">لاحقًا (كما في السبعينية)، <b>سمع دون اكتراث</b>، <b>لم يبالِ</b>: <r v=\"Mark.5.36\"></r>؛ مع المضاف إليه، <r v=\"Matt.18.17\"></r>.†</s>","en":"<f><o>παρ-ακούω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ezra.3.3\"></r>, <r v=\"Ezra.3.8\"></r> (<h n=\"H5674\">עבר</h>, <h n=\"H6213\">עשׂה</h>, c. neg.) <r v=\"Ezra.4.14\"></r> <r v=\"Ezra.7.4\"></r> (<h n=\"H2790\">חרשׁ</h> hi.), <r v=\"Isa.65.12\"></r> (<h n=\"H8085\">שׁמע</h>, c. neg.), <r v=\"1Esd.4.11\"></r>, <r v=\"Tob.3.4\"></r>*;]</e> </et> <s n=\"1.\"><b>to overhear</b>.</s> <s n=\"2.\"><b>to hear amiss</b> or <b>imperfectly</b>.</s> <s n=\"3.\">Later (as in LXX, Polyb., Plut.; also in <g>π.</g>, v. MM, xviii), <b>to hear without heeding</b>, <b>take no heed</b>: <r v=\"Mark.5.36\"></r>; c. gen., <r v=\"Matt.18.17\"></r>.†</s>"},"G3805":{"l":"παθητός","o":1,"ar":"<f>* <o>παθητός</o>، <g>-ή, -όν</g></f> <s n=\"1.\"><b>من تألّم</b>.</s> <s n=\"2.\"><b>قابل للألم</b> أو <b>مقدَّر له أن يتألم</b>: <r v=\"Acts.26.23\"></r>.†</s>","en":"<f>* <o>παθητός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>πάσχω</g>),</e> </et> <s n=\"1.\"><b>one who has suffered</b>.</s> <s n=\"2.\"><b>subject to suffering</b> (R, mg., v. M, <i>Pr.</i>, 222) or <b>destined to suffer</b> (AV, R, txt.): <r v=\"Acts.26.23\"></r>.†</s>"},"G3871":{"l":"παρακαλύπτω","o":1,"ar":"<f><o>παρα-καλύπτω</o>،</f> <s><b>غطّى</b> بتعليق شيء بجانبه، <b>أخفى</b>: مجازيًا، <r v=\"Luke.9.45\"></r>.†</s>","en":"<f><o>παρα-καλύπτω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Isa.44.8\"></r> (<h n=\"H6342\">פּחד</h>), <r v=\"Ezek.22.26\"></r> (<h n=\"H5956\">עלם</h> hi.)*;]</e> </et> <s><b>to cover</b> by hanging something beside, <b>to hide</b>: metaph. (as Plat., al.), <r v=\"Luke.9.45\"></r>.†</s>"},"G3827":{"l":"πάμπολυς","o":1,"ar":"<f>** <o>πάμπολυς</o>، <g>-πόλλη, -πολυ</g></f> <s><b>كثير جدًّا</b>، <b>عظيم جدًّا</b>: <r v=\"Mark.8.1\"></r>، في النص المستلَم (والترجمة المنقحة وغيرها: <g>πάλιν πολλοῦ</g>).†</s>","en":"<f>** <o>πάμπολυς</o>, <g>-πόλλη, -πολυ</g></f> <et> <e t=\"derivation\">(&lt; <g>πᾶς</g>, <g>πολύς</g>),</e> <e t=\"septuagint\">[in Sm.: <r v=\"Job.36.31\"></r>, <r v=\"Ps.40.6\"></r> <r v=\"Ps.89.51\"></r>*;]</e> </et> <s><b>very much</b>, <b>very great</b>: <r v=\"Mark.8.1\"></r>, Rec. (RV, Edd., <g>πάλιν πολλοῦ</g>).†</s>"},"G3812":{"l":"παιδιόθεν","o":1,"ar":"<f><o>παιδιόθεν</o></f> ظرف، <s>= في الكلاسيكية <g>ἐκ παιδός</g>، <g>παιδίου</g>؛ <b>منذ الصبا</b>: <r v=\"Mark.9.21\"></r>.†</s>","en":"<f><o>παιδιόθεν</o></f> <et> <e t=\"derivation\">(&lt; <g>παιδίον</g>),</e> </et> adv., <et> <e t=\"septuagint\">[in LXX: <r v=\"Gen.47.3\"></r>*;]</e> </et> <s>= cl. <g>ἐκ παιδός</g>, <g>παιδίου</g>, <b>from childhood</b>: <r v=\"Mark.9.21\"></r>.†</s>"}});A.got[38]=1})(window.ABBOTT=window.ABBOTT||{D:{},got:{}});